insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('6ab5f440-af61-563d-b068-bc8a4016e54f', '2026-27', 'optional', 'SAT and ACT scores are not required for general admission; submitted official scores may be used for orientation placement or to fulfil Core Competency Requirements.', '4f8d48c1-2549-557e-a857-cee91741d164');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, app_fee_usd, notes, source_id) values
 ('6ab5f440-af61-563d-b068-bc8a4016e54f', '2026-27', array['common_app']::text[], '500-word application essay strongly encouraged (optional); Honors College applicants add supplemental materials.', 80, 'Fee is $50 for Arizona residents and $80 for non-Arizona residents or residents of other U.S. states (the page does not name an international rate). Recommendations are not listed among review materials; optional materials are SAT/ACT, resume and personal statement. Some students are admitted to The A Center (undeclared support program).', '4f8d48c1-2549-557e-a857-cee91741d164');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('9a2c6df6-f6aa-5a94-aaa3-23343d94e9df', '6ab5f440-af61-563d-b068-bc8a4016e54f', '2026-27', 'application', 'EA', 'Early Action (priority for admission, merit aid and Honors College), fall 2027', '2026-11-01', '2027-01-15', 'Decision release begins January 15, 2027. Applications after Nov 1 move to Regular Decision, reviewed on a space-available basis with decisions released in batches in the spring; no fixed Regular Decision deadline is published for first-year main campus.', 'a226761e-6fba-5e8c-b35a-8f2775f627ac'),
 ('b96cc335-f4fa-5b6c-8922-5a7b1fd6c9ab', '6ab5f440-af61-563d-b068-bc8a4016e54f', '2026-27', 'deposit', 'RD', 'National College Decision Day (enrollment fee)', '2027-05-01', null, 'Page ''highly encourages'' claiming a spot by May 1; not stated as a hard deadline.', 'a226761e-6fba-5e8c-b35a-8f2775f627ac');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('6ab5f440-af61-563d-b068-bc8a4016e54f', 'required_nonnative', 'Required for applicants whose primary language is not English or who attended school in a non-English-speaking country, regardless of citizenship. Waived with 3 years of regular English classes at a C or better at an accredited American high school (domestic or abroad), 3 years at an English-medium high school with C, IB English A HL 5, IGCSE/O-Level English C, or a US college composition course with C. Scores must be dated within 2 years.', '7529e283-7935-5738-8aaf-f06af530328f');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
