insert into cost_aid (institution_id, year, tuition_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, notes, source_id) values
 ('affbc0b4-52e4-5a17-8da3-d70fa14231f3', '2023-2024', 58560, 22346, 1300, 2100, 82076, 'need_aware_limited', true, false, true, 'College Scorecard (IPEDS 2023-24): tuition includes required fees; on-campus cost of attendance.; Admission is need-aware for international financial aid applicants. Need-based aid is limited to the Global Scholars program (four-year full-tuition scholarships plus extra grants based on need, for ED or RD applicants who file the CSS Profile) and the Canadian Scholarship. All international applicants are also considered for merit awards (Women''s Leadership quarter-tuition, Presidential half-tuition, Weissman full-tuition via separate application).', '0a865253-3aa6-571e-9ac0-2b1449f90b1a');
