insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('ff2bedac-6e20-5610-a123-b0eb89e63d92', '2026-27', 'optional', 'Boston College offers a test-optional admission policy; applicants who do not submit scores receive full consideration. Non-submitters remain eligible for the Gabelli Presidential Scholars Program if they apply by November 1. English proficiency exams are still required for non-US citizens (the test-optional policy does not cover them).', '3fd2edee-2572-56d6-aea3-12adb0b6d8fe');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, portfolio, app_fee_usd, fee_waiver, midyear_report, notes, source_id) values
 ('ff2bedac-6e20-5610-a123-b0eb89e63d92', '2026-27', array['common_app','questbridge']::text[], 'BC Writing Supplement via Common App: answer one of the first four 2026-27 prompts (400-word limit); Human-Centered Engineering applicants answer Prompt 5 instead.', 2, true, 'Arts portfolios submitted through SlideRoom.', 85, true, true, 'Fee waivers are for US citizens or permanent residents with financial hardship, requested through the Common App. Mid-year report required for Regular Decision and deferred Early Decision applicants. No general admission interview is described; optional InitialView video interview for students at national schools in China. Spring first-year admission available (not for Human-Centered Engineering or Nursing).', '2c4aad05-2dde-57d7-bca6-e5e7f98a9100');
