insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('a2d4d562-20f9-5be0-b31a-3ebfe8cc2628', '2026-27', 'optional', 'Test optional for first-year applicants applying through fall 2028 and spring 2029; applies to all schools and scholarship programs. Applicants indicate on the application whether they want scores considered (cannot be changed after submitting). BU superscores SAT and ACT. International applicants must still submit TOEFL, IELTS or Duolingo.', 'b2d003d0-6ce6-5455-a1b9-49f1f2b4c12b');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, portfolio, app_fee_usd, fee_waiver, midyear_report, notes, source_id) values
 ('a2d4d562-20f9-5be0-b31a-3ebfe8cc2628', '2026-27', array['common_app','questbridge']::text[], 'BU supplemental essay in addition to the Common App personal statement; Kilachand Honors College applicants write an additional required essay.', 1, true, 'College of Fine Arts: audition (Music, Theatre) or portfolio (Visual Arts, some Theatre programs) required.', 80, true, true, 'Applicants must choose a BU school or college; admission may be offered to College of General Studies or another program instead. CSS Profile and FAFSA deadlines apply to US citizens and permanent residents only. Optional InitialView/Vericant interview for international applicants.', 'b2d003d0-6ce6-5455-a1b9-49f1f2b4c12b');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('c8ae143c-5cfc-5b36-94ca-7ca2f5087a3c', 'a2d4d562-20f9-5be0-b31a-3ebfe8cc2628', '2026-27', 'application', 'ED', 'Early Decision (binding)', '2026-11-02', '2026-12-14', 'Enrollment deposit due early-mid January. Page lists month/day only (Nov 2, Dec 14); read as the fall 2026 cycle.', '7a979812-8a64-5c70-90ab-d10651e6a3ea'),
 ('dbf20649-3705-5ac9-83fa-6ebd7bf2fbf6', 'a2d4d562-20f9-5be0-b31a-3ebfe8cc2628', '2026-27', 'application', 'ED2', 'Early Decision 2 (binding)', '2027-01-05', '2027-02-08', 'Enrollment deposit due late February. School of Theatre prescreens due December 1.', '7a979812-8a64-5c70-90ab-d10651e6a3ea'),
 ('b1196774-7b3e-531f-a755-bba4cec47c4d', 'a2d4d562-20f9-5be0-b31a-3ebfe8cc2628', '2026-27', 'application', 'RD', 'Regular Decision', '2027-01-05', null, 'Decision-release date not published on the deadlines page.', '7a979812-8a64-5c70-90ab-d10651e6a3ea'),
 ('c4cec0a8-29dd-5cc1-9b42-c98269786c1b', 'a2d4d562-20f9-5be0-b31a-3ebfe8cc2628', '2026-27', 'scholarship', null, 'Merit scholarship consideration (e.g. Presidential Scholarship)', '2026-12-01', null, 'Complete the admission application by December 1; no separate scholarship application.', '26478ddf-4404-5b2e-bf76-716ed3ac39be'),
 ('7fe601a4-394d-5b05-be44-70a67097abcc', 'a2d4d562-20f9-5be0-b31a-3ebfe8cc2628', '2026-27', 'financial_aid', null, 'CSS Profile and FAFSA (Early Decision)', '2026-11-02', null, 'US citizens and permanent residents only.', '7a979812-8a64-5c70-90ab-d10651e6a3ea'),
 ('8abaf942-71a9-5651-a667-e2253fe41026', 'a2d4d562-20f9-5be0-b31a-3ebfe8cc2628', '2026-27', 'financial_aid', null, 'CSS Profile and FAFSA (ED2 and Regular Decision)', '2027-01-05', null, 'US citizens and permanent residents only.', '7a979812-8a64-5c70-90ab-d10651e6a3ea'),
 ('bf5bbe45-a306-5ae6-82c4-1e48c27fde78', 'a2d4d562-20f9-5be0-b31a-3ebfe8cc2628', '2026-27', 'deposit', null, 'Enrollment deposit (Regular Decision)', '2027-05-01', null, null, '7a979812-8a64-5c70-90ab-d10651e6a3ea');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('a2d4d562-20f9-5be0-b31a-3ebfe8cc2628', 'required_nonnative', 'Required if first language is not English. Waiver requests must be submitted by the application deadline with a complete application and are at the Board of Admissions'' discretion. Applicants whose first language is English but speak another language at home may submit results to show fluency. Not accepted: IELTS Indicator, TOEFL ITP Plus, TOEFL Essentials, IELTS One Skill Retake.', 'c386ad0b-e008-5852-abd9-e7b38715636d');
insert into english_requirements (institution_id, status, source_id, test_key, recommended_total, min_subscores, notes)
select 'a2d4d562-20f9-5be0-b31a-3ebfe8cc2628'::uuid, 'required_option', 'c386ad0b-e008-5852-abd9-e7b38715636d'::uuid, v.* from (values
 ('TOEFL_IBT', 90, '{"each_section": 20}'::jsonb, 'Old 0-120 scale (reports before Jan 21, 2026). Most competitive applicants have a composite of at least 90-100 and 20+ in each section. These are competitive benchmarks, not a stated hard minimum.'),
 ('TOEFL_IBT_2026', 5.0, null, 'For score reports from Jan 21, 2026: most competitive applicants have a total/overall of 5.0 or higher; component scores reviewed for consistency.'),
 ('IELTS', 7.0, null, 'IELTS Academic. A total/overall of 7 or higher satisfies BU''s English requirement for all programs; component scores reviewed for consistency.'),
 ('DUOLINGO', 125, null, 'Most competitive applicants have a total of at least 125-135. BU requires the total score and all subscores.')) v;
