insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('04cf3b47-2569-5e90-88bc-892d892aec23', '2026-27', 'optional', 'Test-optional since 1969; applicants choose whether SAT/ACT scores are reviewed and can suppress scores until the application deadline. Both SAT and ACT are superscored. Self-reported scores accepted; scores verified for enrolling students.', '9e54f602-0a53-506f-aa3b-080e9ca3284e');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, app_fee_usd, css_profile_required, notes, source_id) values
 ('04cf3b47-2569-5e90-88bc-892d892aec23', '2026-27', array['common_app','coalition','questbridge']::text[], false, 1, true, 70, true, '$70 fee, automatically waived for aid applicants and first-generation students. Bowdoin Supplement has only two optional short essays. Three recommendations: counselor, one academic teacher, and one ''other'' (second teacher or a coach/employer/community member). Optional video response and optional independent interviews (InitialView / Vericant). International applicants (not Canadians) submit CSS Profile only after admission.', 'c64eb233-4c64-573a-ba69-181cdf60867e');
