insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('af0bdaaa-8391-58d4-9cf4-3aef2df3ad94', '2026-27', 'optional', 'Brandeis has been test-optional since 2013. Applicants indicate on the Common App whether they want SAT/ACT scores considered; all applicants are considered for merit scholarships regardless. Self-reported scores are accepted (official scores required before matriculation). The ACT science section is not required.', 'd940bef5-2752-573e-85f7-a6cff610e815');
insert into application_requirements (institution_id, cycle, platforms, teacher_recs, counselor_rec, interview, app_fee_usd, fee_waiver, css_profile_required, midyear_report, notes, source_id) values
 ('af0bdaaa-8391-58d4-9cf4-3aef2df3ad94', '2026-27', array['common_app','coalition']::text[], 1, true, 'by_invitation', 80, true, true, true, 'School report plus a letter of recommendation from a secondary school official, and one letter from a teacher of a core academic course. Senior mid-year grades are required for Regular Decision. ED applicants also submit an Early Decision Agreement Form. Interviews with Brandeis admissions are by invitation only; international applicants are strongly encouraged to use InitialView or Vericant (record and submit by Nov 15 for ED I, Jan 15 for ED II/RD). CSS Profile is required of international students seeking aid (and CSS Profile plus FAFSA for domestic aid applicants).', 'e6179866-42f4-5fdf-a410-2eaa8f0f1566');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('d0ac4c31-222b-5e73-ad35-fce03e22a362', 'af0bdaaa-8391-58d4-9cf4-3aef2df3ad94', '2026-27', 'application', 'ED', 'Early Decision I', '2026-11-02', '2026-12-15', 'Binding. Page lists month and day only; the same table gives spring admission for the January 2027 semester, so it is the 2026-27 cycle.', '8b0401dd-0975-56ae-adc8-a6584f7eca59'),
 ('4da45dbe-3e8d-5924-879d-fcbc67119fb3', 'af0bdaaa-8391-58d4-9cf4-3aef2df3ad94', '2026-27', 'application', 'EA', 'Early Action', '2026-11-02', '2027-02-01', 'Non-binding.', '8b0401dd-0975-56ae-adc8-a6584f7eca59'),
 ('c40eddbd-eb28-5b28-9288-a4fe1efec783', 'af0bdaaa-8391-58d4-9cf4-3aef2df3ad94', '2026-27', 'application', 'ED2', 'Early Decision II', '2027-01-15', '2027-02-15', 'Binding.', '8b0401dd-0975-56ae-adc8-a6584f7eca59'),
