insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('af0bdaaa-8391-58d4-9cf4-3aef2df3ad94', 'required_nonnative', 'Exempt if you have spent four or more years in a high school whose full academic curriculum is in English (request a waiver in the DEISconnect portal after applying), or if you apply directly from a United World College campus. Scores accepted from TOEFL iBT, IELTS, Duolingo (must come directly from the testing agency) or Cambridge C1 Advanced / C2 Proficiency; scanned copies of TOEFL, IELTS and Cambridge are accepted.', 'e6179866-42f4-5fdf-a410-2eaa8f0f1566');
insert into english_requirements (institution_id, status, source_id, test_key, notes)
