 ('act', '1802', null, 'd940bef5-2752-573e-85f7-a6cff610e815'::uuid),
 ('toefl', null, 'No TOEFL code published on the pages opened (3092 is the SAT and CSS Profile code); select Brandeis by name.', 'e6179866-42f4-5fdf-a410-2eaa8f0f1566'::uuid),
 ('ielts', null, 'No numeric code published on Brandeis''s pages.', 'e6179866-42f4-5fdf-a410-2eaa8f0f1566'::uuid),
