insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('461ac61b-e5fb-59fc-bb4c-0f9ea5ca2be4', '2026-27', 'optional', 'Applicants choose on the application whether UB considers their SAT/ACT scores; test scores are not required for an admission decision and applicants who opt out are still reviewed for merit scholarships.', 'df167920-2ad6-53be-8599-02736e7525ac');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('461ac61b-e5fb-59fc-bb4c-0f9ea5ca2be4', '2026-27', array['common_app','coalition','own']::text[], 50, 'Complete only one of ApplySUNY (select ''Buffalo, University at''), the Common App or the Coalition application; $50 non-refundable fee. Holistic review considers academic marks, test scores, essay and recommendations; UB strongly recommends at least one letter of recommendation (up to three accepted). Transcripts are self-reported. Intended major selection matters: direct admission to accounting and business management is limited enrollment, engineering applications get an additional review, and acting, dance, music theatre, music and BFA design/technology require an audition or portfolio/interview.', '794cc718-0b4b-51c9-a534-643527cc86b8');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('814130c8-cff5-588b-bf06-c24f1b261f50', '461ac61b-e5fb-59fc-bb4c-0f9ea5ca2be4', '2026-27', 'application', 'EA', 'Early Action (non-binding)', '2026-11-01', 'Early Action applicants get a priority response and priority consideration for merit scholarships; decisions come on a rolling basis (CDS). Enrollment deposit due May 1 or 10 days after acceptance, whichever is later. Honors College priority consideration Dec 15.', 'c4927dcc-597f-5df7-9cde-306986481c60'),
 ('6d9ef4ea-5168-534e-bec1-d6d04179ecb1', '461ac61b-e5fb-59fc-bb4c-0f9ea5ca2be4', '2026-27', 'application', 'RD', 'Regular Decision application completion deadline', '2027-02-01', 'Applications can continue to be submitted after this date until capacity is reached. Page states these dates for the international first-year tab; no year is printed, so they are taken as the current cycle (application opens Aug 1).', '794cc718-0b4b-51c9-a534-643527cc86b8'),
 ('6b02f479-3145-55e3-b5f9-bf8aa9134ae6', '461ac61b-e5fb-59fc-bb4c-0f9ea5ca2be4', '2026-27', 'other', 'RD', 'Honors College priority consideration', '2026-12-15', null, 'c4927dcc-597f-5df7-9cde-306986481c60');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('461ac61b-e5fb-59fc-bb4c-0f9ea5ca2be4', 'required_nonnative', 'In general required for applicants whose native language is not English and who completed any part of high school in a non-English-speaking country. Alternatives accepted instead of a test: ACT English and reading each 18+, SAT ERWS 500+, AP English Language 4+ or a B in the class, British IGCSE/GCE English result of C. Scores must be under two years old.', 'df167920-2ad6-53be-8599-02736e7525ac');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
