insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('3ed3721b-9031-5fe0-89f6-7beea7e2f31f', '2026-27', 'required', 'SAT or ACT required for fall 2027 entry; ACT writing/science not required. Tests are superscored. Only enrolling students must send official scores. All AP and IB exams taken must be reported.', 'a66553d0-7fce-5a1b-b2b8-63acbc696ae9');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, portfolio, app_fee_usd, fee_waiver, css_profile_required, midyear_report, notes, source_id) values
 ('3ed3721b-9031-5fe0-89f6-7beea7e2f31f', '2026-27', array['common_app','questbridge']::text[], '5 required responses (STEM academic interest, scholarly character, two scientific-drive prompts, fun question) plus 1 optional short answer', 2, 'Optional portfolio (STEM and/or non-STEM)', 85, true, true, true, 'Two teacher recommendations: one STEM (calculus or beyond, chemistry, physics or biology), one humanities/social science. A counselor letter is submitted as part of the School Report (not listed as a separate requirement). Interview policy not stated on the pages read. QuestBridge applicants pay no fee. CSS Profile requirement is from the financial aid page for international applicants (page text is for fall 2026 entry).', 'a54d8121-3fb7-5e10-99c7-e65a55338098');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_note, notes, source_id) values
