insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('5a8f2d66-5e64-5432-a0fb-a69a713858ba', '2026-27', 'optional', 'Clemson has adopted a test-optional policy; applicants are not required to submit SAT or ACT scores. Clemson superscores both tests and does not require the SAT/ACT essay. Students may switch their score-use preference up to Nov 1 (Early Action) or Jan 10 (Regular Decision).', '295ea803-00ea-5458-9433-e60d463afe68');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, counselor_rec, app_fee_usd, notes, source_id) values
 ('5a8f2d66-5e64-5432-a0fb-a69a713858ba', '2026-27', array['common_app','coalition','own']::text[], 0, false, 70, 'Clemson Application, Coalition (Scoir) and Common App are all accepted with no preference. Personal statements, letters of recommendation and resumes can be uploaded in the portal but are not required. First-year applicants self-report their transcript through STARS; official transcripts are required only after admission. International applicants pick two intended majors, and South Carolina residents get priority as a public university. The international page lists May 1 as the last day to apply for fall entry (apply much earlier for scholarship and capacity reasons); the page does not state a year, so dates are taken as the current cycle (application opens Aug 1).', '295ea803-00ea-5458-9433-e60d463afe68');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('5db013d0-6ed0-5156-b8db-dbb6f281ec42', '5a8f2d66-5e64-5432-a0fb-a69a713858ba', '2026-27', 'application', 'EA', 'Early Action (non-binding)', '2026-10-15', 'Required materials due Nov 1; decisions released mid-December (no exact date published).', '295ea803-00ea-5458-9433-e60d463afe68'),
 ('ae12ba96-8f5f-57eb-a700-edef0f24577d', '5a8f2d66-5e64-5432-a0fb-a69a713858ba', '2026-27', 'application', 'RD', 'Regular Decision', '2027-01-01', 'Also the deadline for scholarship consideration. Required materials due Jan 10; decisions released mid-February (no exact date published).', '295ea803-00ea-5458-9433-e60d463afe68');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('5a8f2d66-5e64-5432-a0fb-a69a713858ba', 'required_nonnative', 'The English test can be waived for students for whom English is the primary language or one of the official languages. Transfer applicants who passed English Composition I and II with a B or better at a US institution are also exempt.', 'a142c236-95b8-5252-963d-67d0553c5a38');
