insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('f3343b57-3aa7-595f-a784-3933c99db9d2', '2026-27', 'blind', 'CSU does not require SAT/ACT. The admissions site says submitted scores are reviewed only if the applicant emails a request, are not given much weight, and are not used to decline an application or in scholarship decisions; CDS C8A answers ''No'' to using SAT/ACT in admission.', '782b7d17-f58f-5000-95c4-21ee16966cd6');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, fee_waiver, notes, source_id) values
 ('f3343b57-3aa7-595f-a784-3933c99db9d2', '2026-27', array['common_app']::text[], 65, true, 'International freshmen apply with the Common App: 250-650 word essay, most recent transcripts (certified English translation if needed), passport copy and financial-support documents for the I-20. The $65 fee is the international freshman fee (CDS C13 lists $50 generally). Review is holistic; students with a 3.0+ GPA and a steady or upward trend are generally admitted. Recommendation letters and interview are not mentioned on the page.', '7672c3a8-f09a-5a51-9287-5c8573d9018d');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('e9923cc1-0db3-57b4-b043-6b4ba9bf940e', 'f3343b57-3aa7-595f-a784-3933c99db9d2', '2026-27', 'application', 'EA', 'Early action (non-binding), fall 2027 entry', '2026-11-15', 'Complete file by Nov. 15 for full consideration and automatic scholarship review by Jan. 15. The page prints dates without a year; taken as the current cycle. CDS C14: priority date Nov. 15, closing date July 31, rolling notification from Oct. 1.', '7672c3a8-f09a-5a51-9287-5c8573d9018d'),
 ('1311d221-1260-52cb-bd2d-068dca7501ac', 'f3343b57-3aa7-595f-a784-3933c99db9d2', '2026-27', 'application', 'RD', 'Regular decision, fall 2027 entry', '2027-01-15', 'Full consideration by Jan. 15, scholarship review by Feb. 28; applications are then reviewed on a rolling basis until mid-summer but scholarships may not be available. The page prints no year.', '7672c3a8-f09a-5a51-9287-5c8573d9018d'),
 ('4144c4c6-e6d4-5038-a6bf-a0078fc02c8c', 'f3343b57-3aa7-595f-a784-3933c99db9d2', '2026-27', 'scholarship', null, 'International scholarships: highest consideration', '2026-12-15', 'Dec. 15 is highest consideration and Mar. 15 regular consideration; no separate scholarship application. The page prints no year.', '7fd9d347-aff8-5e36-a20d-127c67ce59d8');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('f3343b57-3aa7-595f-a784-3933c99db9d2', 'required_nonnative', 'No test needed with SAT EBRW 520+, ACT English/Reading 20+, IB HL English 5+, AP English Language or Literature 4+, IGCSE/A-level English C or better (official, not predicted), WAEC/WASSCE English B3+, or Gaokao English 105+ plus an online interview. Exempt if English is the first language and the applicant is from Australia, Canada, Ireland, New Zealand or the UK. Conditional admission: applicants who meet academic standards but lack a qualifying score enroll in CSU''s Intensive English Program (most finish in 1-2 semesters; IEP courses carry no degree credit), then move into degree courses; send evidence by June 1 (fall) or Nov. 15 (spring).', '4bfb508f-40ca-5c3a-a70a-8dd352c95daf');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'f3343b57-3aa7-595f-a784-3933c99db9d2'::uuid, 'required_option', '4bfb508f-40ca-5c3a-a70a-8dd352c95daf'::uuid, v.* from (values
 ('TOEFL_IBT', 72, 'Exams before Jan. 2026. Paper-based TOEFL considered case by case. No subscore minimum listed.'),
 ('TOEFL_IBT_2026', 4.0, 'Exams after Jan. 2026; CSU accepts both score types. The page does not name the 1-6 scale.'),
 ('IELTS', 6.0, 'IELTS Academic.'),
 ('DUOLINGO', 110, null)) v;
