insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('0c810646-0f7d-5e9e-84dd-5116ec9750b2', '2026-27', 'optional', 'SAT or ACT scores are not required; submitting them can improve chances of admission and they will not be used to deny an application. CDS C8 also lists scores as not required but considered if submitted.', '9a2eceb5-4e28-5c58-a315-2ad7585db3d0');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('0c810646-0f7d-5e9e-84dd-5116ec9750b2', '2026-27', array['own']::text[], 75, 'International first-year applicants apply online and pay a non-refundable $75 fee (the CDS lists $50 generally; fee waiver requests are possible). Admission is rolling with decisions about 10 business days after a complete application. Engineering/Design/Computing and Architecture & Planning have extra major requirements after admission.', '9a2eceb5-4e28-5c58-a315-2ad7585db3d0');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('528ae1e8-a744-545e-9768-cb5f1e0d22b0', '0c810646-0f7d-5e9e-84dd-5116ec9750b2', '2026-27', 'scholarship', null, 'Priority scholarship consideration, fall 2027', '2027-03-01', 'Spring priority is Oct. 1. The page prints no year; taken as the current cycle.', '9a2eceb5-4e28-5c58-a315-2ad7585db3d0'),
 ('49abe9f0-a771-588d-adab-288718232c34', '0c810646-0f7d-5e9e-84dd-5116ec9750b2', '2026-27', 'application', 'ROLLING', 'Fall 2027 application deadline (applicants outside the U.S.)', '2027-07-15', 'Spring is Dec. 1, summer May 1.', '9a2eceb5-4e28-5c58-a315-2ad7585db3d0'),
 ('13d33abd-2c38-5dcf-bcb2-df2852df42a6', '0c810646-0f7d-5e9e-84dd-5116ec9750b2', '2026-27', 'application', 'ROLLING', 'Fall 2027 application deadline (applicants already inside the U.S.)', '2027-08-08', 'Spring is Jan. 4, summer May 23.', '9a2eceb5-4e28-5c58-a315-2ad7585db3d0');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('0c810646-0f7d-5e9e-84dd-5116ec9750b2', 'required_nonnative', 'No test needed for citizens of Antigua & Barbuda, Australia, Bahamas, Barbados, Belize, Canada, Dominica, Grenada, Guyana, Ireland, Jamaica, Malta, New Zealand, St Kitts & Nevis, St Vincent & the Grenadines, Trinidad & Tobago or the UK, or with a U.S. high school diploma (1+ year in the U.S. with college-prep English) or a qualifying English-medium credential, or by finishing Level 5 at the CU Denver ESL Academy. Additional accepted scores: ACT English 18, SAT EBRW 480, AP English Literature 3, IB English A 4, GCE A-Level English E. Conditional admission: undergraduates (except Nursing) below the minimum can enter the LynxDirect Pathway in the ESL Academy with TOEFL iBT 70 (new scale 3.5), IELTS 6.0, Duolingo 95, or completed ESL Level 4. Letters of instruction are not accepted. MyBest TOEFL and superscored IELTS accepted.', '8be598d7-5359-5d69-b6ce-5e0444b58f7b');
