insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('65582c3f-c577-56d6-aa54-6dfa61d44f76', '2026-27', 'optional', 'No Harm Test-Optional for fall entry: applicants choose whether to supply scores; scores are used only if they strengthen the application. Required for the BA/BS+MD and BS+OD Early Assurance programs. Choosing test-optional does not affect aid or merit scholarships.', 'b0360aa4-e12c-5be5-85d9-23a54d292ee8');
insert into application_requirements (institution_id, cycle, platforms, teacher_recs, counselor_rec, app_fee_usd, css_profile_required, notes, source_id) values
 ('65582c3f-c577-56d6-aa54-6dfa61d44f76', '2026-27', array['common_app','coalition']::text[], 0, true, 65, true, 'One counselor recommendation required (BA/BS+MD: counselor plus a science teacher). Essay of 250-650 words via Common App or Coalition. Portfolio required for some Westphal programs. CSS Profile required for institutional need-based aid (international applicants too); FAFSA also for US citizens and permanent residents. Dates below are applied to the fall 2027 cycle; the deadline page gives month/day and notes a 2026-2027 CSS Profile only for winter entry.', 'e3afa94b-3be4-5020-8847-e1f84e9069fc');
