insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('8b8b98b6-5774-572f-9165-4f70cbccd04a', '2026-27', 'optional', 'Emory is test optional for first-year students starting in fall 2027; SAT/ACT scores are not required and are reviewed as a demonstration of academic preparation if submitted. Self-reported scores are accepted; enrolling students must send official scores for verification. Emory superscores the SAT and ACT.', '7e5ed3dd-b28e-5962-b937-026c6e1cb2ea');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, interview, app_fee_usd, fee_waiver, css_profile_required, midyear_report, notes, source_id) values
 ('8b8b98b6-5774-572f-9165-4f70cbccd04a', '2026-27', array['common_app','questbridge']::text[], 'Common App personal essay plus Emory short-answer college questions (submitted through the Common App).', 2, true, 'optional_informational', 75, true, true, true, 'Two recommendations from core academic teachers. Counselor submits the school report and transcript; ED II and RD applicants need a counselor mid-year report. Emory does not offer evaluative interviews with staff or alumni; international applicants may submit an optional InitialView video interview (strongly recommended for applicants from Mainland China). CSS Profile is for need-based aid applicants only (deadlines vary by plan). The $75 fee is waived for QuestBridge applicants. (Mid-year report requirement is from the FAQs page.)', 'e8f43c0e-e921-5bf6-9af2-809f02cfa44e');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('3f220d98-1a04-551e-9ed5-f7222ead0a85', '8b8b98b6-5774-572f-9165-4f70cbccd04a', '2026-27', 'application', 'ED', 'Early Decision I', '2026-11-01', '2026-12-15', 'Binding. Page lists month and day only; interpreted as the fall 2027 entry cycle. Notification is ''by December 15''. International students who need aid should apply Regular Decision (see aid page).', '9a565053-4ec9-5690-b73b-90b480fad1f1'),
 ('dccbd9b4-0edd-59f1-a8e2-fe72c3f15e31', '8b8b98b6-5774-572f-9165-4f70cbccd04a', '2026-27', 'application', 'ED2', 'Early Decision II', '2027-01-01', '2027-02-15', 'Binding. Notification ''by February 15''.', '9a565053-4ec9-5690-b73b-90b480fad1f1'),
 ('b6720784-2d25-50cf-8858-d746358e5920', '8b8b98b6-5774-572f-9165-4f70cbccd04a', '2026-27', 'application', 'RD', 'Regular Decision', '2027-01-01', '2027-04-01', 'Notification ''by April 1''.', '9a565053-4ec9-5690-b73b-90b480fad1f1'),
 ('ad7656f5-58e1-5d83-9149-6866c19bd0e4', '8b8b98b6-5774-572f-9165-4f70cbccd04a', '2026-27', 'scholarship', null, 'Emory University Scholar Programs', '2026-11-15', '2027-03-01', 'Merit scholarship programs; the international aid page tells international applicants to apply to the Scholar programs before December.', '9a565053-4ec9-5690-b73b-90b480fad1f1'),
 ('e3a1825d-4f6f-560f-82fb-0b35dbd387f9', '8b8b98b6-5774-572f-9165-4f70cbccd04a', '2026-27', 'financial_aid', 'ED', 'Financial aid deadline - Early Decision I', '2026-12-02', null, null, '9a565053-4ec9-5690-b73b-90b480fad1f1'),
 ('8abd93e5-c1c4-5803-815d-2ab95028b840', '8b8b98b6-5774-572f-9165-4f70cbccd04a', '2026-27', 'financial_aid', 'ED2', 'Financial aid deadline - Early Decision II', '2027-01-06', null, null, '9a565053-4ec9-5690-b73b-90b480fad1f1'),
 ('47da7ba8-6185-5b7a-9694-60fe2d92fed4', '8b8b98b6-5774-572f-9165-4f70cbccd04a', '2026-27', 'financial_aid', 'RD', 'Financial aid deadline - Regular Decision', '2027-02-10', null, 'The international aid page separately says to complete the CSS Profile before February 5.', '9a565053-4ec9-5690-b73b-90b480fad1f1');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('8b8b98b6-5774-572f-9165-4f70cbccd04a', 'required_nonnative', 'Exempt if you have an SAT Evidence-Based Reading and Writing score of 700+, an ACT English subscore of 30+, or spent the most recent four years in a school where English is the language of instruction for all academic subjects (excluding world languages). Otherwise one of TOEFL, IELTS or Duolingo is required. Emory states it does not use strict cutoffs.', '7e5ed3dd-b28e-5962-b937-026c6e1cb2ea');
insert into english_requirements (institution_id, status, source_id, test_key, recommended_total, notes)
