insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('b0e7c0b2-088c-546d-9fb6-0034a581bc20', '2024-2025', 25234, 22074, 4464, 19, 2, 'Baseline from IPEDS (fall 2024 entering class): counts from the ADM2024 file via the Urban Institute Education Data Portal (25,234 applied, 22,074 admitted, 4,464 enrolled), matching College Navigator''s 87% admitted / 20% yield. George Mason''s 2025-2026 Common Data Set exists on oiep.gmu.edu but returned HTTP 403 (bot protection) to direct and tool fetches, so CDS-only items (SAT total, GPA, residency and international splits, admission factors) are not added. SAT/ACT percentiles cover only the 19% (829) / 2% (80) of enrollees who submitted scores. Undergrad enrollment 28,334 and nonresident undergrads 1,574 are IPEDS fall 2024.', '59f5a73c-cba3-5a59-bd99-6ef56eb9cdfa', 'admissions_site');
