select 'b0e7c0b2-088c-546d-9fb6-0034a581bc20'::uuid, 'direct_major', false, v.* from (values
 ('39503cb5-8e26-5460-af63-0112b1b5fcea'::uuid, 'Computer Science and Engineering (College of Engineering and Computing)', 'engineering', 'Needs four years of high school math including a course above Algebra II, plus SAT Math 550 / ACT Math 24 or B (not B-) or higher in all math through Algebra II. Admitted students who do not qualify are placed in CEC Undeclared.'),
 ('8fc82947-3d64-5882-96ff-6053516b1735'::uuid, 'Nursing, BSN (School of Nursing)', 'nursing', 'Direct-admission freshman applications get a second review by the School of Nursing admission committee; described as highly competitive. Students admitted to the university but not to the School become undeclared.')) v;

