 ('act', 'No ACT code is published on the freshman or international pages.', 'd9f0bd79-9741-54a1-8a4c-24960a09fd53'::uuid),
 ('toefl', 'No TOEFL institution code is published on the international page.', '12379c66-5e93-5f96-a4e2-9bd48dad5e05'::uuid),
 ('ielts', 'No institution code is listed.', '12379c66-5e93-5f96-a4e2-9bd48dad5e05'::uuid),
 ('duolingo', 'No institution code is listed.', '12379c66-5e93-5f96-a4e2-9bd48dad5e05'::uuid),
