 ('IELTS', 'required_option', 6.0, null),
 ('DUOLINGO', 'required_option', 100, null),
 ('PTE', 'required_option', 48, 'Pearson PTE Academic.'),
 ('CAMBRIDGE', 'accepted', null, 'A pass on C1 Advanced or C2 Proficiency (the page gives no numeric score).')) v;
