insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('6782144d-72fa-5e08-9354-5af82cd895ba', '2026-27', 'optional', '''No harm'' policy: scores are used only if they help. SAT/ACT are not required of international applicants educated abroad, but are required for academic scholarships, direct admission to the Tippie College of Business and the Honors Program (per the international requirements page); the first-year page says all admitted applicants are also considered for scholarships without a score. SAT/ACT can also satisfy the English requirement.', '6581edab-d4e9-5d85-8d22-e337a70b1693');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('6782144d-72fa-5e08-9354-5af82cd895ba', '2026-27', array['common_app','own']::text[], 55, 'International first-years need a 3.0 GPA (U.S. B or better) on academic courses, three years of secondary coursework, completion of secondary school and the college-specific high school course requirements (CLAS, Engineering, Business or Nursing). $55 non-refundable fee as listed on the First-Year Admissions page (a separate international rate is not stated); fee waiver available. Rolling decisions from August. Applicants who meet the Regent Admission Index (RAI) with a test score usually hear sooner. Nursing and Medical Laboratory Science have additional international requirements.', '83a8a2ed-40d0-502d-b9b8-69342e20fa8d');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('d0697774-a6fa-5367-9a9a-b1a7a6aa09c6', '6782144d-72fa-5e08-9354-5af82cd895ba', '2026-27', 'application', 'EA', 'Early Action deadline, fall 2027 (documents by Nov. 9)', '2026-11-02', 'Decisions on or before late January. Shown on the first-year page; it does not say whether international applicants are treated differently.', 'f5b45b96-f007-5e74-bc57-22587414c1f9'),
 ('13fbe184-92b9-5bdc-b4a1-85eaca3479ae', '6782144d-72fa-5e08-9354-5af82cd895ba', '2026-27', 'application', 'RD', 'Regular admission deadline, fall 2027 (documents by Feb. 8)', '2027-02-01', 'Decisions on or before early March. Applicants after Feb. 1 are not eligible for merit scholarships and are admitted case by case, space permitting.', 'f5b45b96-f007-5e74-bc57-22587414c1f9'),
 ('ee36ad27-56ff-543c-8ed2-30d67a090be1', '6782144d-72fa-5e08-9354-5af82cd895ba', '2026-27', 'deposit', null, 'Summer/fall acceptance deadline', '2027-05-03', null, '83a8a2ed-40d0-502d-b9b8-69342e20fa8d'),
 ('9faaf94e-34e6-51d2-8b25-517db9b0129f', '6782144d-72fa-5e08-9354-5af82cd895ba', '2026-27', 'scholarship', null, 'Complete application for merit scholarship consideration (National Scholars Award)', '2027-02-01', 'Test scores taken through Dec. 12, 2026 count; scores arriving before Feb. 8, 2027 can still be used.', '1ac3e2d2-8540-58c4-9228-1e8b2787e62e');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('6782144d-72fa-5e08-9354-5af82cd895ba', 'required_nonnative', 'Waived for citizens (listing English as first language) of countries where English is official (the page lists, among others, Australia, Canada, Ireland, Nigeria, South Africa and the UK), 3+ years at a U.S. high school, or 30 s.h. of U.S. college credit at a 2.50 GPA. Duolingo and PTE are not listed on the undergraduate page. Also accepted: TOEFL Essentials 9, ACT English 21, SAT Reading+Writing 540, AP English 4, IB HL English 5. Students admitted on a TOEFL below 100 (or with an IELTS/other subscore below the threshold) must take ESL courses (ESL4100/4130/4180/4200) unless they test out on the on-campus English Placement Exam. Admission with ESL coursework is the pathway for lower scores.', '0135ea04-fa83-5e3b-bcf8-d44bfaca447f');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, min_subscores, notes)
