insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('4fbefaaf-e530-51da-b425-1ee363f88308', '2026-27', 'optional', 'ACT/SAT are not required for admission and are considered if submitted; the Wildcat Nonresident Award does not use scores. The College of Architecture, Planning and Design strongly encourages a score.', '89500df9-6e60-5a8d-b4f2-8c61002ec48d');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('4fbefaaf-e530-51da-b425-1ee363f88308', '2026-27', array['common_app','own']::text[], 80, 'Formula-style admission: international first-years need a high school curriculum from an accredited secondary school and a minimum 2.5 GPA on a 4.0 scale. $80 undergraduate international application fee is printed on the K-State Online international page (the Manhattan pages do not state one; the domestic CDS fee is $40). Final transcripts are needed on arrival if admitted in the final school year. Scholarship awards are automatic on admission; international students apply for the K-State Scholarship Network (KSN) by March 15.', '89500df9-6e60-5a8d-b4f2-8c61002ec48d');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('f2a4a9f7-df6b-5177-bd9f-b3a05bca564b', '4fbefaaf-e530-51da-b425-1ee363f88308', '2026-27', 'priority', null, 'Priority application date (fall 2027)', '2026-12-01', 'From CDS C14 (priority date December 1st, no closing date); the Manhattan site refers to a ''Priority Application Date'' for scholarships without printing it. The year is inferred as the 2026-27 cycle.', '6b4be16e-be34-5414-a1b6-4b87f0567fa7'),
 ('6a174562-3626-5141-a7c3-c2eec51d3206', '4fbefaaf-e530-51da-b425-1ee363f88308', '2026-27', 'application', 'ROLLING', 'International undergraduate fall application deadline', '2027-08-01', 'Printed on the K-State Online international page (fall Aug. 1, spring Jan. 1, summer May 1). The Manhattan international pages print no closing date and the CDS says there is none, so apply early; the Dec. 1 priority date applies to scholarship consideration.', 'd822c605-94fc-5e6b-acb5-eea1a6e834ca'),
 ('d5d57288-e5af-50a4-b5bd-28aac587eb2a', '4fbefaaf-e530-51da-b425-1ee363f88308', '2026-27', 'scholarship', null, 'K-State Scholarship Network (KSN) profile deadline for international students', '2027-03-15', 'College and departmental awards after admission. Freshman scholarship upgrades use grades and scores received by April 1.', '6b4be16e-be34-5414-a1b6-4b87f0567fa7');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('4fbefaaf-e530-51da-b425-1ee363f88308', 'required_nonnative', 'English proficiency is not required for admission, but must be met before enrolling in courses. Options: (1) waive English classes with a qualifying score or transcript (scores under 2 years old); (2) pre-place with TOEFL, IELTS or DET scores; (3) be admitted without proof and take the K-State English Language Program (ELP) placement test (WildCAT online or EPT on arrival) and be placed into intensive, part-time or full-time academic classes. ELP courses may count toward the degree depending on the major. Also accepted: SAT EBRW 460, ACT English 21, IB, A-level and O-level English, Eiken Pre-1; transfer students with English Composition I and II at C or higher and four years of U.S. high school English at C or higher are exempt.', '49a6abf3-309d-51b7-9102-35dbe13f0673');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, notes)
