insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('dbd170dc-72e4-5c8c-b251-688e0cbcf0c1', '2026-27', 'required', 'SAT or ACT is required for first-year applicants (the CLT is also accepted from fall 2027). Minimums: SAT 500 EBRW and 490 Math, or ACT 18 English-or-Reading and 18 Math, in addition to the GPA minimum. Architecture needs SAT 500/570 or ACT 18 / 23 Math. KSU superscores SAT and ACT separately but does not mix them.', 'd601440f-dcd6-550d-aadc-57a27ead4e76');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('dbd170dc-72e4-5c8c-b251-688e0cbcf0c1', '2026-27', array['own']::text[], 40, 'Application fee $40. Fall 2027 first-year admission requires a minimum 3.0 high school GPA (2.5 through summer 2027) recalculated on the 17-unit Required High School Curriculum, plus qualifying SAT/ACT. International applicants need an official document-by-document credential evaluation including GPA from a NACES or AICE member service (e.g. IEE, The Evaluation Company) and English proficiency. The pages do not mention essays or recommendations; whether the Common App is accepted is not stated on these pages.', 'd601440f-dcd6-550d-aadc-57a27ead4e76');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('fa692388-f820-5213-8c8a-3e7b90d156c5', 'dbd170dc-72e4-5c8c-b251-688e0cbcf0c1', '2026-27', 'priority', null, 'Fall 2027 international priority application deadline (documents due Nov. 16, 2026)', '2026-11-02', 'Priority gives early access to on-campus housing and orientation sign-up, and priority consideration for the Flight to Excellence out-of-state waiver (freshmen: Nov. 2, 2026).', 'd601440f-dcd6-550d-aadc-57a27ead4e76'),
 ('89f1558a-b004-547f-b57b-1f29e6b621e3', 'dbd170dc-72e4-5c8c-b251-688e0cbcf0c1', '2026-27', 'application', 'ROLLING', 'Fall 2027 international regular application and document deadline', '2027-07-01', 'Classes begin Aug. 23, 2027. Spring 2027 entry: application Nov. 16, 2026, documents Dec. 1, 2026.', 'd601440f-dcd6-550d-aadc-57a27ead4e76');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('dbd170dc-72e4-5c8c-b251-688e0cbcf0c1', 'required_nonnative', 'Non-native speakers must validate English proficiency; being exempt from SAT/ACT does not exempt a non-native applicant from English proficiency. Alternatives to the tests below: SAT EBRW 500, ACT English or Reading 18, MET 77, EIKEN Pre-1, IGCSE/O-Level/GCSE/A-Level English grade B or better, completion of a USG campus ESL program or English Composition I with C or better. Conditional admission is available while enrolled in KSU''s Intensive English Program (IEP); full admission is reviewed after completing the highest IEP level.', 'd601440f-dcd6-550d-aadc-57a27ead4e76');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'dbd170dc-72e4-5c8c-b251-688e0cbcf0c1'::uuid, 'required_option', 'd601440f-dcd6-550d-aadc-57a27ead4e76'::uuid, v.* from (values
 ('TOEFL_IBT', 79, 'Exams taken before Jan. 21, 2026.'),
 ('TOEFL_IBT_2026', 4.0, 'Exams taken on or after Jan. 21, 2026, minimum 4 on the 1-6 scale.'),
 ('IELTS', 6.0, null),
 ('DUOLINGO', 115, 'Page lists ''115 (Writing Section)''; it is not clear whether the 115 applies to the overall score or only the writing sub-score.'),
