insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('9a7251f1-26c2-54b2-a6be-c1df5b422279', '2023-2024', 14821, 11937, 3117, 15, 88, 'Baseline from IPEDS (fall 2023 entering class). UofL''s 2024-25 CDS is linked from its website only through a document-viewer page that could not be downloaded as text, and no 2025-26 CDS is posted, so SAT total, GPA and residency splits are not added. College Navigator for fall 2024 shows 15,668 applicants, 79% admitted, SAT ERW 530/580/640, Math 510/570/630, ACT 19/23/27. Undergrad enrollment (16,194) and nonresident-alien undergraduates (233) are fall 2023 IPEDS (EF2023A); student-to-faculty ratio 14:1 from College Navigator.', '182491c6-d233-5e13-8147-8c9d67c5b084', 'admissions_site');
