 ('act', '2220', null, '911cf86e-677a-5682-bdc7-98bc0b3e66ee'::uuid),
 ('toefl', null, 'The international admissions page does not print a TOEFL institution code.', '1b14ea30-97b8-53af-9211-293641b0f9c6'::uuid),
 ('ielts', null, 'No institution code is listed.', '1b14ea30-97b8-53af-9211-293641b0f9c6'::uuid),
