insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, meets_full_need, merit_scholarships, merit_separate_app, notes, source_id) values
 ('90f9a1f6-6c35-50ac-a4d0-0ec62e5f8c12', '2024-2025', 10202, 27637, 12902, 1200, 6409, 48148, 'merit_only', false, true, false, 'College Navigator (IPEDS) 2024-25: tuition includes required fees; on-campus cost of attendance for out-of-state students is $48,148. MSU''s own current tuition page was not read, so current-year figures may differ.; Non-resident academic scholarship is awarded automatically on admission by 9th-11th grade GPA, renewable up to 4 years (fall 2027 entrants): $12,000/yr at 3.30-3.59, $16,000/yr at 3.60-4.09, $19,000/yr at 4.10+. Competitive awards (e.g. Maroon and White) need the General Scholarship Application and qualifying SAT/ACT by Dec. 1. Students with active agent contracts are ineligible. Need-based aid for internationals is not mentioned.', '46d070a8-9acb-558b-b8ac-7d9cc8cedc35');
