insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('a88c321f-2c01-5ce0-9d0c-59dea94f0e2b', '2026-27', 'optional', 'ACT/SAT are not required for general admission; scores may be required for the College of Architecture and the College of Engineering, and domestic scholarship awards can use the highest composite score.', 'ce479f4a-fbc7-5b63-bf9d-2784b27950e1');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('a88c321f-2c01-5ce0-9d0c-59dea94f0e2b', '2026-27', array['common_app','own']::text[], 45, 'Admission is granted to international applicants who meet the core coursework requirements (4 units upper-level math, 3 natural sciences, 3 social sciences, 4 English/native language) and demonstrate English proficiency; the first-year page also sets performance routes (3.0 GPA, or ACT 20, or SAT 1040, or top half of class) for guaranteed admission, and other applicants go to committee review. Required documents in MyRED: final secondary school transcript signed and stamped by a principal, school certificate or diploma, and English scores. $45 fee by credit card. Late applications may be waitlisted. Some colleges (Architecture, Education, Engineering, Journalism) set higher English minimums; applicants not in those colleges can enter via the Explore Center.', 'ce479f4a-fbc7-5b63-bf9d-2784b27950e1');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('38b64536-a1f0-5033-bf25-89a0eeff6775', 'a88c321f-2c01-5ce0-9d0c-59dea94f0e2b', '2026-27', 'priority', null, 'Priority admission deadline, fall 2027', '2026-11-01', '2027-02-11', 'Applying by Nov. 1 gets scholarship offers on Feb. 11, 2027; later applicants are notified on a rolling basis from Feb. 25. Application opens Aug. 1.', 'ed77e9bb-fd8f-5f78-b34d-9ffd720f9da2'),
 ('1fed6410-754c-5f6d-8b6f-4b3fb47c482f', 'a88c321f-2c01-5ce0-9d0c-59dea94f0e2b', '2026-27', 'application', 'ROLLING', 'Final application and enrollment deposit deadline, fall 2027', '2027-05-01', null, 'Late applications may be waitlisted behind applicants who meet assured admission requirements. International applicants must submit all materials by May 1 to be considered for academic scholarships.', 'ed77e9bb-fd8f-5f78-b34d-9ffd720f9da2'),
 ('1ca914ff-e25b-5c3a-948b-c29d91a3b043', 'a88c321f-2c01-5ce0-9d0c-59dea94f0e2b', '2026-27', 'scholarship', null, 'All materials due for international academic scholarship consideration', '2027-05-01', null, null, 'ed77e9bb-fd8f-5f78-b34d-9ffd720f9da2'),
 ('3c9d93a2-f063-5db7-b27f-d6bf3185f5f1', 'a88c321f-2c01-5ce0-9d0c-59dea94f0e2b', '2026-27', 'other', null, 'Final deadline to submit English proficiency scores (fall 2027)', '2027-07-15', null, null, 'ed77e9bb-fd8f-5f78-b34d-9ffd720f9da2');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('a88c321f-2c01-5ce0-9d0c-59dea94f0e2b', 'required_nonnative', 'Waived for graduates of a U.S. high school or applicants with 30 transferable semester hours from a U.S. college. Applicants who do not meet the English requirement can be conditionally admitted through the Intensive English Program (IEP): recommended minimum TOEFL 35, IELTS 5.0 or Duolingo 70; progress to full admission is reviewed at the end of each semester; IEP application deadlines May 1 (summer/fall) and Dec. 1 (spring), $45 fee. Also accepted: ACT English 20, SAT Reading and Writing 520 (SAT Writing 26), and the Nebraska English Language Test (ELT) 80 with a 78 subscore (85 for Journalism). PTE and Cambridge are not listed.', 'ce479f4a-fbc7-5b63-bf9d-2784b27950e1');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, min_subscores, notes)
select 'a88c321f-2c01-5ce0-9d0c-59dea94f0e2b'::uuid, 'required_option', 'ce479f4a-fbc7-5b63-bf9d-2784b27950e1'::uuid, v.* from (values
 ('TOEFL_IBT', 79, '{"each_section": 18}'::jsonb, 'Old 0-120 scale. College minimums: Engineering 80, Journalism and Mass Communications 100. Paper-based test: 550 with 55 subscores (Journalism 600).'),
 ('TOEFL_IBT_2026', 4.0, '{"each_section": 4.0}'::jsonb, 'New 1-6 scale, general admission.'),
 ('IELTS', 6.5, '{"each_section": 6.0}'::jsonb, 'Journalism and Mass Communications requires 7.0.'),
 ('DUOLINGO', 110, '{"each_section": 105}'::jsonb, 'Architecture and Education and Human Sciences require 120.')) v;
