insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('686653c1-e590-55bd-8477-28552c9b3669', '2026-27', 'optional', 'Northeastern is test-optional ''for the foreseeable future''; applicants who apply without scores are not penalized. If submitted, Northeastern super-scores and considers the better of SAT or ACT. All enrolling students must send final exam results (e.g. AP/IB/national exams).', 'bae24fe2-a97a-5ab7-83ef-507b1083d36e');
insert into application_requirements (institution_id, cycle, platforms, teacher_recs, counselor_rec, interview, app_fee_usd, fee_waiver, css_profile_required, midyear_report, notes, source_id) values
 ('686653c1-e590-55bd-8477-28552c9b3669', '2026-27', array['common_app','coalition']::text[], 1, true, 'optional_informational', 75, true, true, true, 'One teacher and one school counselor recommendation (1-2 extra optional). Mid-year report for Regular Decision and deferred applicants. Northeastern offers no alumni or on-campus interviews but evaluates optional third-party InitialView or Vericant video interviews (due Nov 15 for ED I, Dec 1 for EA, Jan 15 for ED II, Feb 1 for RD). International applicants must submit the Declaration and Certification of Finances. CSS Profile and FAFSA apply only to US citizens, permanent residents and eligible non-citizens seeking need-based aid. Creative portfolio encouraged for CAMD; NYC performing arts require audition.', 'bae24fe2-a97a-5ab7-83ef-507b1083d36e');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
