insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('686653c1-e590-55bd-8477-28552c9b3669', 'required_nonnative', 'Waiver if you will have completed 4 consecutive full-time academic years in high schools and universities where English is the primary language of instruction for all courses except foreign language courses; request through the Application Status Check. Northeastern may request proof of English proficiency from any applicant. Not accepted: IELTS Indicator, PTE Academic Online, TOEFL Essentials, TOEFL iBT Paper Test, TOEFL ITP.', 'b411ac9f-2236-5852-b827-8b3746fb593f');
