insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('ff88d87f-2080-5255-91cf-71645b8f2cb1', '2026-27', 'flexible', 'Test requirement depends on US-scale GPA for internationals: 3.0-4.0 is admissible without SAT/ACT; 2.5-2.99 needs SAT 880+ or ACT 16+; 2.0-2.49 needs SAT 960+ or ACT 18+. Scores also raise scholarship awards.', '4dc877bd-06be-5736-9089-62d56a1edd0d');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('ff88d87f-2080-5255-91cf-71645b8f2cb1', '2026-27', array['common_app','own']::text[], 75, 'Apply with the UM application or the Common App; the $75 fee cannot be waived for international students. Transcript must cover at least 6 semesters and counts as official only if sent by the school or via Common App. Competitive programs (Honors College, Croft, Pharmacy, etc.) have separate applications.', '9991cc6c-ad57-512e-8269-882e37bd3e49');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('40a8ce2c-983e-557c-8a43-19cb49b1b43b', 'ff88d87f-2080-5255-91cf-71645b8f2cb1', '2026-27', 'application', 'ROLLING', 'Recommended international deadline, fall 2027 entry', '2027-02-01', 'Admission is rolling with decisions in a few weeks; Ole Miss recommends international students apply before Feb. 1 (fall) or Oct. 1 (spring) to leave time for the visa process. The page prints no year, so it is taken as the current cycle.', '4dc877bd-06be-5736-9089-62d56a1edd0d');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('ff88d87f-2080-5255-91cf-71645b8f2cb1', 'required_nonnative', 'Exempt: completed the Intensive English Program Advanced Plus level with a B or higher; 2+ years at and graduation from an accredited U.S. high school (domestic standards then apply); citizens of listed English-speaking countries. Scores must be under two years old. Conditional admission is possible below TOEFL 69 / IELTS 5.5 / PTE 47 (separate Intensive English application). Scores 69-78 TOEFL, 5.5 IELTS or 47-52 PTE may be admitted but must take IE 090/091 in the first term.', '8027490c-b806-5c17-bfc4-3a926a0cffd2');
