insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('bce097fc-89d4-5738-9212-5701db129383', '2026-27', 'optional', 'Test optional: students choose whether to self-report SAT or ACT scores; unreported scores are not considered even if sent. If ACT is submitted, the Core ACT plus Science is required (sections are superscored). Official scores are needed only from enrolling students.', 'd3ccbc2c-0f68-53a1-b9df-13775f6e253b');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, app_fee_usd, css_profile_required, notes, source_id) values
 ('bce097fc-89d4-5738-9212-5701db129383', '2026-27', array['common_app','coalition','questbridge']::text[], true, 2, true, 80, true, '$80 fee, waived through the Pomona Access Pass form. Pomona-specific essays: 150-word academic interest statement plus a 250-word short response. Two core-subject teacher letters; school report and counselor recommendation; mid-year report by Feb 15. Applicants from non-English-medium schools must submit TOEFL, IELTS or Duolingo. Interview policy not confirmed; third-party InitialView/Vericant/Duolingo interviews are optional supplements. International aid applicants file the CSS Profile (code 4607) or, if the fee is a burden, Pomona''s International Financial Aid Application.', 'd3ccbc2c-0f68-53a1-b9df-13775f6e253b');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('d9422d56-398d-541e-a43f-1b571ce007d1', 'bce097fc-89d4-5738-9212-5701db129383', '2026-27', 'application', 'ED', 'Early Decision I', '2026-11-08', '2026-12-15', 'Notification ''by'' Dec 15; reply Jan 1. CAUTION: the overview table does not print a year and some Pomona admissions pages still say ''Fall 2026 admission''; Pomona''s Nov 8 / Jan 8 dates are fixed each year, but verify. Financial aid forms due Nov 15.', 'd3ccbc2c-0f68-53a1-b9df-13775f6e253b'),
 ('3b7ce9bb-2512-550a-9392-ab3680422aec', 'bce097fc-89d4-5738-9212-5701db129383', '2026-27', 'application', 'ED2', 'Early Decision II', '2027-01-08', '2027-02-15', 'Notification ''by'' Feb 15; reply March 1. Year not printed on page; verify. Financial aid forms due Jan 15.', 'd3ccbc2c-0f68-53a1-b9df-13775f6e253b'),
 ('d6dd5c55-b006-585f-befd-56579efb0579', 'bce097fc-89d4-5738-9212-5701db129383', '2026-27', 'application', 'RD', 'Regular Decision', '2027-01-08', '2027-04-01', 'Notification ''by'' April 1; reply May 1. Year not printed on page; verify. Financial aid forms due Jan 15.', 'd3ccbc2c-0f68-53a1-b9df-13775f6e253b');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('bce097fc-89d4-5738-9212-5701db129383', 'required_nonnative', 'Required if English is not the primary language of instruction at your secondary school. Accepts TOEFL iBT (incl. Special Home Edition), TOEFL ITP Plus for China, IELTS or Duolingo; self-reported scores allowed, official report required on enrolling. Sub-scores have no minimum. The listed values are described as minimum scores for admission.', '6cc30460-9ae4-5d9a-9fd7-2c0072fe527b');
insert into english_requirements (institution_id, status, test_key, min_total, notes, source_id)
select 'bce097fc-89d4-5738-9212-5701db129383'::uuid, 'required_option', v.* from (values
 ('TOEFL_IBT', 100, 'Minimum for iBT and iBT Special Home Edition (old 0-120 scale). TOEFL ITP Plus for China Solution: 627.', '6cc30460-9ae4-5d9a-9fd7-2c0072fe527b'::uuid),
 ('TOEFL_IBT_2026', 5, 'Taken from a ''5 - Minimum TOEFL'' statistic on the international page; the scale is not stated there, interpreted as the new 1-6 scale. Verify.', '9f972e8c-38f8-5f7d-be19-1f5f9d2c4989'::uuid),
 ('IELTS', 7, null, '6cc30460-9ae4-5d9a-9fd7-2c0072fe527b'::uuid),
 ('DUOLINGO', 130, null, '6cc30460-9ae4-5d9a-9fd7-2c0072fe527b'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, notes, source_id) values
 ('bce097fc-89d4-5738-9212-5701db129383', '2023-2024', 68670, 22464, 1100, 1500, 89414, 'need_aware_full_need', true, true, false, 'College Scorecard (IPEDS 2023-24): tuition includes required fees; on-campus cost of attendance.; Admission is need-aware for international applicants, but Pomona meets 100% of demonstrated need of every admitted international student, without loans in the package. No merit or athletic scholarships. Aid must be requested when applying; it cannot be added after the admission application is submitted. About 41% of international students receive aid (average nearly $74,000/yr).', '45bbd462-601c-5b50-9dbd-1e3a4b7fb181');
