insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, notes, source_id, source_note) values
 ('acbf81e7-aae6-5e60-b80a-26230d495f5e', '2024-2025', 9077, 8248, 1502, 'Baseline from IPEDS (fall 2024 entering class). PSU''s posted Common Data Set archive stops at 2022-23, so no CDS was used; GPA distribution, residency and international splits, and SAT/ACT percentiles are not loaded. College Scorecard lists only SAT midpoints (about 575 reading and 550 math). Undergraduate enrollment (15,426) and the 18:1 student-faculty ratio are from PSU''s fall 2025 facts page, which says international students are 4% of all students (all levels); an undergraduate-only international count was not found.', '76b8af45-487a-571d-ae1c-e10f8633f89d', 'admissions_site');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('acbf81e7-aae6-5e60-b80a-26230d495f5e', '2026-27', 'optional', 'Submitting SAT or ACT scores is optional and not required to receive an admission decision. For admitted international students on visas, an SAT EBRW of 560+ can also be used as proof of English proficiency.', '1a39bb48-8d69-51bc-b3e8-be881e33a8ae');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('acbf81e7-aae6-5e60-b80a-26230d495f5e', '2026-27', array['own']::text[], 60, 'Apply through PSU''s online application ($60 for international first-years). International first-year applicants need a cumulative GPA of at least 2.5 on the U.S. 4.0 scale (PSU converts it) and completed secondary school equivalent to U.S. high school; applicants below 3.0 GPA are considered by holistic review. Unofficial transcripts from non-U.S. schools can be used to get a decision; official ones are needed later. English test results are asked of admitted students. Allow four to six weeks for a decision once documents are in.', 'a337eef7-ba7a-5e13-b102-4b55fdd968ca');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('eace58da-c9bf-5f44-a8c9-46ead41786bb', 'acbf81e7-aae6-5e60-b80a-26230d495f5e', '2026-27', 'application', 'ROLLING', 'Fall 2027 application deadline (domestic and international undergraduates)', '2027-08-01', 'Application opens Aug 1, 2026; documents are due by Aug 5, 2027 and fall term begins Sept 27, 2027. PSU publishes no earlier international cutoff; allow time for the I-20 and visa.', '621c9584-fee2-5c9f-8030-04fe4db67eaa'),
 ('e53a4f70-5ffd-5440-9f6a-544366855929', 'acbf81e7-aae6-5e60-b80a-26230d495f5e', '2026-27', 'priority', null, 'Priority date: PSU scholarships and Tuition Free Degree', '2027-03-01', 'March 1 is the deadline for PSU general and most departmental scholarships; international students are also automatically reviewed for the International Achievement Scholarship at admission with no separate application.', '621c9584-fee2-5c9f-8030-04fe4db67eaa'),
 ('3b6d25b9-7e85-5a92-8d48-2498c1b5192b', 'acbf81e7-aae6-5e60-b80a-26230d495f5e', '2026-27', 'deposit', null, 'Fall term enrollment confirmation priority deadline', '2027-06-15', 'The same date is the on-campus housing application priority deadline.', '621c9584-fee2-5c9f-8030-04fe4db67eaa');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('acbf81e7-aae6-5e60-b80a-26230d495f5e', 'required_nonnative', 'Required of admitted undergraduates on non-immigrant visas. Alternatives to a test: U.S. associate degree (2.50 GPA, WR 121 plus another college writing course at C- or better), a bachelor''s or higher degree from a university in Australia, English-speaking Canada, Ghana, Ireland, Kenya, New Zealand, Nigeria, South Africa, Uganda, the UK, the U.S. or Zimbabwe, citizenship of those countries with English-medium schooling, an IB diploma with 30+ points, Level 5 of the Pacific International Academy ESL program at the University of Portland (PSU''s ESL partner), or PCC ESOL Level 8 with B or better. Scores must be under 2 years old; IELTS One Skill Retake is not accepted.', '50db6507-b441-5284-b271-20a32f43619f');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, min_subscores, notes)
select 'acbf81e7-aae6-5e60-b80a-26230d495f5e'::uuid, 'required_option', '50db6507-b441-5284-b271-20a32f43619f'::uuid, v.* from (values
 ('TOEFL_IBT', 71, '{"reading": 15, "writing": 15}'::jsonb, 'Tests taken before Jan 21, 2026.'),
 ('TOEFL_IBT_2026', 4.0, '{"reading": 3.5, "writing": 3.5}'::jsonb, 'Tests taken on or after Jan 21, 2026 (1-6 scale).'),
 ('IELTS', 6.0, '{"reading": 6.0, "writing": 6.0}'::jsonb, 'Academic IELTS; One Skill Retake scores not accepted.'),
 ('DUOLINGO', 110, null, null),
 ('PTE', 53, null, 'Academic PTE.')) v;
