insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('7d143b07-c6d4-5ab5-aa68-8a12e1b0fea0', '2026-27', 'optional', 'Test-optional for the 2026-27 cycle; Rice ''recommends'' submitting SAT/ACT if available but applicants without scores get full consideration. Scores are superscored; self-reported scores allowed, official scores required only if you enroll. SAT/ACT essay not considered.', '45214849-fdae-5867-b7c4-4cb5168bb7ec');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, app_fee_usd, notes, source_id) values
 ('7d143b07-c6d4-5ab5-aa68-8a12e1b0fea0', '2026-27', array['common_app','questbridge']::text[], 'Rice writing supplement: two 150-word prompts and one 500-word prompt (choice of two). Architecture adds two 250-word prompts and a creative portfolio.', 2, true, 75, 'Two core-academic teacher letters (ideally one in the intended area of study) and one school counselor letter. Interviews are optional, virtual, and not guaranteed; the page does not say whether they are evaluative. Optional 60-90 second Glimpse video. QuestBridge applicants get automatic fee waivers. CSS Profile: the international aid page says Rice uses the CSS Profile for international students; the first-year page does not name an aid form for domestic applicants.', '45214849-fdae-5867-b7c4-4cb5168bb7ec');
