insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('39006720-3c32-5bfb-9538-2bb95f2eec56', '2026-27', 'optional', 'Test optional for all applicants through all phases of review, with no disadvantage or scholarship penalty; applicants indicate on the application whether they apply test-optional or test-flexible. English-language testing is still required for some non-native speakers.', 'c663f656-41fd-5191-97c2-564fd25eb806');
insert into application_requirements (institution_id, cycle, platforms, teacher_recs, counselor_rec, interview, app_fee_usd, fee_waiver, midyear_report, notes, source_id) values
 ('39006720-3c32-5bfb-9538-2bb95f2eec56', '2026-27', array['common_app','coalition']::text[], 1, true, 'optional_evaluative', 50, true, true, 'Common App or Coalition (Scoir). International applicants: secondary transcript, one teacher recommendation (up to three accepted), school report/counselor recommendation, mid-year report, English exam or waiver, and either the International Financial Support Form (no need-based aid requested) or the CSS Profile (school code 2928; Profile opens Oct 1). Interview is optional but strongly recommended and counts equally in review; InitialView interviews are offered mainly for applicants outside the US. Other application materials are due Dec 1 (ED I), Feb 1 (ED II) and Feb 15 (RD). Eastman School of Music bachelor of music applicants apply through the separate Eastman application. Spring regular decision is Oct 15 (not available for combined degree programs). The page does not state a year, so dates are taken as the current cycle.', '71b6df1c-22f3-5058-9fa1-1de4da767961');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('211b2ac7-dec7-509c-b691-a12d7d4c35bf', '39006720-3c32-5bfb-9538-2bb95f2eec56', '2026-27', 'application', 'ED', 'Early Decision I (binding)', '2026-11-01', null, 'Notification mid-December (no exact date published); reply within 3 weeks of notification; other materials due Dec 1.', '7d655680-06f1-52fa-b8cc-37446f303a94'),
 ('c7fc1a91-df0e-5ca5-bf3d-ee860bd61e73', '39006720-3c32-5bfb-9538-2bb95f2eec56', '2026-27', 'scholarship', 'RD', 'Priority scholarship deadline (non-binding)', '2026-12-01', null, 'Send all application materials by Dec 1 for highest scholarship consideration; notification late February; reply by May 1.', '7d655680-06f1-52fa-b8cc-37446f303a94'),
 ('52bfa03d-6e20-5e44-ae87-b3aa4934b6c7', '39006720-3c32-5bfb-9538-2bb95f2eec56', '2026-27', 'application', 'ED2', 'Early Decision II (binding)', '2027-01-05', null, 'Notification early February (no exact date published); reply within 3 weeks of notification; other materials due Feb 1.', '7d655680-06f1-52fa-b8cc-37446f303a94'),
 ('4cda3945-93fc-521a-ab26-c6efa2bebb23', '39006720-3c32-5bfb-9538-2bb95f2eec56', '2026-27', 'application', 'RD', 'Regular Decision', '2027-01-05', '2027-04-01', 'Reply by May 1; other materials due Feb 15.', '7d655680-06f1-52fa-b8cc-37446f303a94');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('39006720-3c32-5bfb-9538-2bb95f2eec56', 'required_nonnative', 'All international students must submit proof of English proficiency (exam or waiver request). A waiver can be requested if you are a native English speaker or completed at least three years of high school with English as the primary language of instruction. TOEFL My Best scores are not accepted and sub-scores are not combined across sittings. Applicants below the recommended range may be admitted through the English for Academic Purposes Program (EAPP).', '71b6df1c-22f3-5058-9fa1-1de4da767961');
insert into english_requirements (institution_id, status, source_id, test_key, recommended_total, notes)
