insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('8ea56d2f-0a4b-5ce5-a0cd-79ba8b776875', '2026-27', 'optional', '"Test Optional for Fall 2027 Applicants": students may choose whether to submit SAT or ACT scores. Applicants to the Physician-Scientist (B.S./M.D.) Program must submit official scores.', '154bb8a9-868f-55c3-a891-8730b622c9f3');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, interview, app_fee_usd, notes, source_id) values
 ('8ea56d2f-0a4b-5ce5-a0cd-79ba8b776875', '2026-27', array['common_app','own']::text[], 0, 'not_offered', 70, 'Fee is $70, with no fee for applications submitted by December 1 (and for Rensselaer Medalists). The general essay / personal statement satisfies RPI''s essay requirement, except B.S./M.D. (reasons for a medical career) and Architecture (reasons for choosing architecture; B.Arch also needs a creative portfolio). One letter of recommendation from a counselor or teacher, preferably math or science. RPI does not conduct admissions interviews; international applicants may optionally submit an InitialView, Duolingo or Vericant interview and U.S. students an optional GLIMPSE video. FAFSA and CSS Profile are required only if seeking need-based aid (not available to most international students).', '154bb8a9-868f-55c3-a891-8730b622c9f3');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('353d7dce-cf79-5881-b74a-b708c5437782', '8ea56d2f-0a4b-5ce5-a0cd-79ba8b776875', '2026-27', 'application', 'ED', 'Early Decision I', '2026-11-01', '2026-12-12', 'Binding. FAFSA/CSS Profile priority date Nov 15.', '154bb8a9-868f-55c3-a891-8730b622c9f3'),
 ('bb69bcf8-36fa-5205-a7fc-4ab37e3c75e4', '8ea56d2f-0a4b-5ce5-a0cd-79ba8b776875', '2026-27', 'application', 'EA', 'Early Action', '2026-12-01', '2027-01-30', 'Non-binding. No application fee if submitted by Dec 1.', '154bb8a9-868f-55c3-a891-8730b622c9f3'),
 ('51624385-608e-5478-bbe9-47df86460fc6', '8ea56d2f-0a4b-5ce5-a0cd-79ba8b776875', '2026-27', 'application', 'ED2', 'Early Decision II', '2027-01-06', '2027-01-16', 'Binding.', '154bb8a9-868f-55c3-a891-8730b622c9f3'),
