insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('8ea56d2f-0a4b-5ce5-a0cd-79ba8b776875', 'required_nonnative', 'Non-native English speakers (or international students in U.S. colleges for under two years) must submit a test. Exemptions include SAT EBRW 640+, ACT English 22+, IB English A HL 6+, IGCSE / A-AS Level English grade B+, Cambridge B2 First or C1 Advanced score 185+, 3+ years of U.S. secondary education (request via the form on the application status page), or a diploma from a listed English-medium country. Official scores must come directly from the testing agency; self-reported scores are not accepted.', '74c00d66-54ff-5ded-92d3-2a65383a391b');
