insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('443a83c6-2196-5af3-8581-4f0e250fec98', '2026-27', 'optional', 'Test-optional for the 2027 term; scores are not required and not disadvantaged in admission or merit review. Policy for Fall 2028 and later is under review. Applicants answer a Common App Supplement question on whether they want scores considered.', 'e32f8676-4b2c-524f-b6ba-f650b27dbccf');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, interview, app_fee_usd, notes, source_id) values
 ('443a83c6-2196-5af3-8581-4f0e250fec98', '2026-27', array['common_app']::text[], 0, 1, true, 'optional_informational', 75, 'One academic teacher evaluation plus the Secondary School Report. Supplemental essay is optional (150-300 words). No in-person interviews; international applicants may submit an optional InitialView or Vericant video interview (deadlines: Nov 23 for EA/ED I, Jan 15 for ED II, Feb 16 for RD). International applicants also submit the SCU Financial Resource Statement. The deadlines page gives month and day only; the year is inferred for the fall 2027 cycle.', 'ee2b98ae-d626-5744-ad25-e12df9bbafe8');
