insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('eeca49a7-1d63-5014-8498-5a597563d9f5', '2026-27', 'optional', 'Fully test-optional; no preference given either way. SAT and ACT are superscored; self-reported scores accepted. Not required for non-US applicants attending high school outside the US. On the arts-school FAQ SMU says academic merit scholarship consideration for arts applicants requires submitting scores (recommended 1380 SAT or 29 ACT).', 'c4b0ba98-59b3-5ad2-8819-8e9d91e1096d');
insert into application_requirements (institution_id, cycle, platforms, teacher_recs, counselor_rec, app_fee_usd, css_profile_required, notes, source_id) values
 ('eeca49a7-1d63-5014-8498-5a597563d9f5', '2026-27', array['common_app','coalition','own']::text[], 0, true, 60, true, 'Counselor recommendation required; teacher recommendation optional; extracurricular resume requested; essay generally 250-650 words. Also accepts ApplyTexas and the SMU online application. Art, film (BFA), dance, music and theatre applicants need an audition or portfolio (dual admission with Meadows). Need-based aid (US citizens/permanent residents only) uses the CSS Profile (code 6660) plus FAFSA.', 'c4b0ba98-59b3-5ad2-8819-8e9d91e1096d');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('709220a8-5973-587f-8742-bc8980717177', 'eeca49a7-1d63-5014-8498-5a597563d9f5', '2026-27', 'application', 'EA', 'Early Action', '2026-11-01', null, 'Non-binding. Also the scholarship consideration deadline.', 'a3ce04f6-548a-5bd1-a9f5-e0dbfa5531ca'),
 ('b0137350-8611-59b2-9add-aff233730bce', 'eeca49a7-1d63-5014-8498-5a597563d9f5', '2026-27', 'application', 'ED', 'Early Decision I', '2026-11-01', null, 'Binding. Notified by mail in mid-December (no exact date); deposit within two weeks of admission.', 'a3ce04f6-548a-5bd1-a9f5-e0dbfa5531ca'),
 ('7bb6e181-a53b-5a2f-a94b-5812de16391b', 'eeca49a7-1d63-5014-8498-5a597563d9f5', '2026-27', 'application', 'ED2', 'Early Decision II', '2027-01-15', '2027-03-01', 'Binding. Notified by mail by March 1.', 'a3ce04f6-548a-5bd1-a9f5-e0dbfa5531ca'),
 ('0584e21d-ec0a-51e0-a920-bed36934edf2', 'eeca49a7-1d63-5014-8498-5a597563d9f5', '2026-27', 'application', 'RD', 'Regular Decision', '2027-01-15', null, 'Non-binding. Also the scholarship consideration deadline.', 'a3ce04f6-548a-5bd1-a9f5-e0dbfa5531ca'),
 ('5fc9b506-feba-5979-b9b5-62dc1bc6c2ed', 'eeca49a7-1d63-5014-8498-5a597563d9f5', '2026-27', 'financial_aid', 'RD', 'FAFSA priority deadline', '2027-02-15', null, 'Priority deadline for all applicants (US citizens and permanent residents).', 'edee2e2d-0527-5436-baac-2d06f42805ca');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('eeca49a7-1d63-5014-8498-5a597563d9f5', 'required_nonnative', 'Not required for students who attended a high school with an English-based curriculum, or who have SAT critical reading and writing 580+ or ACT writing 25+. Applicants below the recommended minimums may get conditional offers (retake or Intensive English Program).', 'c4b0ba98-59b3-5ad2-8819-8e9d91e1096d');
