insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('20a7084b-1e32-5025-95a5-13e731c8f72c', '2026-27', 'optional', 'Test-optional for first-year applicants through the fall 2029 entry term, with exceptions: the Accelerated Pre-Medicine and Pre-Law programs still require scores (Pre-Med: SAT 1400 or ACT 32 in one sitting, taken before the Nov 1 deadline). Scores may be self-reported in the applicant portal. Stevens has no minimum GPA or test score.', 'e323224d-8574-5dba-9927-86255ca947ba');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, css_profile_required, notes, source_id) values
 ('20a7084b-1e32-5025-95a5-13e731c8f72c', '2026-27', array['common_app','coalition']::text[], 75, true, 'Two letters of recommendation (teacher or school counselor preferred), official transcript and essay. Interview optional for most applicants (international applicants are strongly recommended to interview; InitialView accepted). Music and Visual Arts & Technology applicants are strongly encouraged to submit a portfolio. CSS Profile (code 2819) is required to be considered for Stevens need-based aid; FAFSA for federal/state aid. The timeline page gives month/day only (no year); dates below are applied to the fall 2027 cycle.', 'e323224d-8574-5dba-9927-86255ca947ba');
