insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('c5f81345-7505-52b2-8477-2bfb15a54fd3', '2026-27', 'optional', 'Test optional for applicants (scores sent by the testing agency are considered if submitted). CDS C8F: SAT or ACT is required for the Scholars for Medicine and Scholars for Dental Medicine honors programs.', '28636030-8d82-5192-9d8a-bb449bfd701d');
insert into application_requirements (institution_id, cycle, platforms, teacher_recs, app_fee_usd, notes, source_id) values
 ('c5f81345-7505-52b2-8477-2bfb15a54fd3', '2026-27', array['common_app','own']::text[], 1, 50, 'International applicants use the Common App or the SUNY App (no separate international application); the domestic first-year page also lists the Coalition App. $50 fee. One essay on a topic of choice. ONE letter of recommendation from a teacher or counselor (two teacher letters for honors programs; one from a science/math teacher for WISE). Three most recent years of secondary grades in English. Honors College / WISE / University Scholars need a ~250-word honors statement via the StartSBU portal.', '498ef2f5-4027-5294-a00e-9358481fa6cf');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('f8cea4da-ab0a-5b9f-a993-fe707b380b53', 'c5f81345-7505-52b2-8477-2bfb15a54fd3', '2026-27', 'application', 'EA', 'Fall 2027 Early Action', '2026-11-01', 'Completion deadline: all required materials (application, recommendation, transcripts) must be received. Also the priority deadline for the Honors College, WISE and University Scholars; Simons STEM Scholars is due Nov 1.', '498ef2f5-4027-5294-a00e-9358481fa6cf'),
 ('b402a2eb-6e5b-5c0e-aafb-328f177d3e11', 'c5f81345-7505-52b2-8477-2bfb15a54fd3', '2026-27', 'application', 'RD', 'Fall 2027 Regular Decision', '2027-01-15', 'Completion deadline. Honors programs (excluding Simons STEM) final deadline is Jan 15; later applications are considered on a space-available basis.', '498ef2f5-4027-5294-a00e-9358481fa6cf');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('c5f81345-7505-52b2-8477-2bfb15a54fd3', 'required_nonnative', 'Applicants from native English-speaking countries, and international applicants who attend an English-medium school, are exempt from submitting English proficiency scores. Other accepted evidence: SAT EBRW 480, ACT English 19, IB HL English 5, AP English Language or Literature 3, A-level English C, GaoKao English 125/150, CSAT rank 1. Applicants not meeting the criteria may be considered for conditional admission.', '498ef2f5-4027-5294-a00e-9358481fa6cf');
