insert into cost_aid (institution_id, year, tuition_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, notes, source_id) values
 ('e50b5917-e166-5374-ae30-9474e1d71ed4', '2023-2024', 69226, 21466, 785, 2221, 88696, 'need_aware_full_need', true, true, false, 'College Scorecard (IPEDS 2023-24): tuition includes required fees; on-campus cost of attendance.; Admission is need-aware for international citizens. Admitted international students who applied for aid get 100% of demonstrated need (up to full tuition, with a $800 book allowance), as grants with no loans. Aid must be requested on the admission application. CSS Profile (code 2821) and the ISAFA form are due within 7 days of the admission decision. International students in the Class of 2030 and later get a four-year aid decision.', 'e458986d-3bf7-55b3-b15c-92294f8ba9d3');
