insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, pct_submit_sat, pct_submit_act, notes, source_id) values
 ('f2e822e3-2e82-5f19-9b68-f42810c44c82', '2025-2026', 42824, 36922, 5303, 3434, 2469, 14512, 12641, 24878, 21812, 19, 1, 'CDS C1 (fall 2025 entering class); residency split from the C1 residency table (in-state 14,512 / out-of-state 24,878 / international 3,434 applicants; 12,641 / 21,812 / 2,469 admitted; 3,339 / 1,779 / 185 enrolled). Undergrad enrollment and nonresident count are the B1/B2 ''Total Undergraduates'' figures (21,031; 891 nonresidents). Nonbinding early action (closes 11/1, notified 1/10); no early decision. The GPA table (C11/C12) is blank in the CDS, so gpa_avg and the distribution are left null. SAT middle 50% is for the 19% (1,000 students) who submitted; ACT submitted by 1% (76 students). Temple is test optional.', '69eaa032-e1d7-5a1b-b256-0fb3b72bf35a');
