insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('f2e822e3-2e82-5f19-9b68-f42810c44c82', '2026-27', 'optional', 'Temple is test optional: SAT/ACT are not required and applicants who apply without them are equally eligible for merit scholarships. Official SAT or ACT may be submitted if desired.', '9c9baec0-f949-52c2-9377-226a8a30d4f8');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('f2e822e3-2e82-5f19-9b68-f42810c44c82', '2026-27', array['common_app']::text[], 55, 'Temple uses only the Common App ($55, waiver available). Official secondary transcripts with English translations are required (grades 9-11 plus current 12th-grade progress); letters of recommendation are optional (max two). Some Boyer (music), Tyler (art) and Theater, Film and Media Arts majors need an audition, interview or portfolio. Sponsor must show about $35,000 for the I-20 (FAQ). No separate application for the Sullivan Honors College.', '9c9baec0-f949-52c2-9377-226a8a30d4f8');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('c3a7ccd5-1a1b-5025-b735-ae42963a2571', 'f2e822e3-2e82-5f19-9b68-f42810c44c82', '2026-27', 'application', 'EA', 'Early Action (non-binding)', '2026-11-01', '2027-01-10', 'Apply by Nov. 1 for a decision by Jan. 10. The page prints no year; taken as the current (fall 2027) cycle, application opens Aug. 1. Early Action applicants get priority review.', '9c9baec0-f949-52c2-9377-226a8a30d4f8'),
 ('13b4963a-90ca-5c0e-99b3-6b3c5bd456ce', 'f2e822e3-2e82-5f19-9b68-f42810c44c82', '2026-27', 'application', 'RD', 'Regular Decision', '2027-02-01', null, 'Decision usually shortly after the application is complete; can exceed eight weeks in peak season (Oct-Mar). Pre-Nursing and Musical Theater deadlines are not extended.', '9c9baec0-f949-52c2-9377-226a8a30d4f8'),
 ('f757cdb0-dbbb-5bd5-8e09-15ab8fc4211f', 'f2e822e3-2e82-5f19-9b68-f42810c44c82', '2026-27', 'scholarship', null, '#YouAreWelcomeHere scholarship application', '2027-02-01', null, 'Separate essay or video application for first-year international applicants; $20,000 per year, renewable. Winners announced by Apr. 1.', '05925da5-4355-5265-875e-3ff19061cde7'),
 ('407785e9-b9bd-59ec-a749-886aad08b8a8', 'f2e822e3-2e82-5f19-9b68-f42810c44c82', '2026-27', 'scholarship', null, '#WhyUS scholarship application', '2027-03-01', null, 'Separate creative-prompt application; $2,000-$10,000 per year, up to four years. Winners announced by Apr. 1.', '05925da5-4355-5265-875e-3ff19061cde7'),
 ('c20c24de-16fe-5854-b37f-cf20693ba2bc', 'f2e822e3-2e82-5f19-9b68-f42810c44c82', '2026-27', 'deposit', null, 'Enrollment deposit deadline', '2027-05-01', null, 'Housing is guaranteed for students who commit by May 1.', '9c9baec0-f949-52c2-9377-226a8a30d4f8');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('f2e822e3-2e82-5f19-9b68-f42810c44c82', 'required_nonnative', 'No English test needed if English is your native language or you completed three or more years, at the time of application, in a curriculum where English was the sole language of instruction. Accepted tests: TOEFL iBT (incl. Home Edition), IELTS (or Indicator), PTE Academic, ITEP Academic Plus, Duolingo, Cambridge C1/C2, Michigan English Test, or SAT EBRW 550+. Bridge Program: academically qualified students slightly below the minimums (TOEFL 74-78 / 3.5 new scale, IELTS 5.5, Duolingo 100-105, PTE 50-52, Cambridge 160-179) are fully admitted and take 12 credits with extra English support in the first semester. Applicants with no scores or lower scores may get provisional admission and the Intensive English Language Program (FAQ). Some majors, including Fox School of Business, require higher scores (FAQ: TOEFL 84, IELTS 6.5, PTE 56).', '9c9baec0-f949-52c2-9377-226a8a30d4f8');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, min_subscores, notes)
select 'f2e822e3-2e82-5f19-9b68-f42810c44c82'::uuid, 'required_option', '9c9baec0-f949-52c2-9377-226a8a30d4f8'::uuid, v.* from (values
 ('TOEFL_IBT', 79, '{"each_section": 4.0}'::jsonb, 'Old 0-120 scale, direct admission. The page says ''no sub-scores below 4.0'' beside ''79 old score / 4.0 new score''. Bridge: 74-78. FAQ also lists conditional admission at 65-78. Fox School of Business: 84. Temple TOEFL institution code 2906.'),
 ('TOEFL_IBT_2026', 4.0, '{"each_section": 4.0}'::jsonb, 'New 1-6 scale, direct admission; Bridge 3.5 with no sub-score below 3.5.'),
 ('IELTS', 6.0, null, 'IELTS or IELTS Indicator. Bridge 5.5. Fox School of Business 6.5 (FAQ).'),
 ('DUOLINGO', 110, null, 'Bridge 100-105.'),
 ('PTE', 53, null, 'Bridge 50-52. Fox School of Business 56 (FAQ).'),
 ('CAMBRIDGE', 180, null, 'Cambridge C1 Advanced or C2 Proficiency. Bridge 160-179.')) v;
