insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('d5e1a4ce-6a1b-5c22-b3bb-c2404137110a', '2026-27', 'optional', 'Tufts is test-optional for all undergraduate applicants; applicants choose whether to submit SAT/ACT scores and cannot change that choice after submitting. Self-reported scores are accepted (official scores required on matriculation). Tufts superscores. Proof of English proficiency is still required for certain applicants.', '25bc3d61-fb25-5aab-89bf-68095dee78c3');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, app_fee_usd, notes, source_id) values
 ('d5e1a4ce-6a1b-5c22-b3bb-c2404137110a', '2026-27', array['common_app','coalition','questbridge']::text[], 'Two required short-answer prompts: #1 how you have learned about and engaged with Tufts (75-150 words); #2 depends on the school applied to (Arts and Sciences, Engineering or BFA; 100-200 words).', 75, 'Common App, Coalition App powered by Scoir and QuestBridge are all accepted with no preference. Applicants apply to one school (Arts and Sciences, Engineering or the School of the Museum of Fine Arts). Fee amount is from the CDS 2025-2026 (C13); fee waiver for international aid applicants is described on the aid page. Number of teacher recommendations and interview policy were not found on the pages opened. CSS Profile is requested of admitted international aid applicants after admission (ISFAA accepted at application).', '453a5c9f-0e20-5693-8b25-b3541ceeb626');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('16253daf-bf86-5195-9ab5-f20a6cf581c0', 'd5e1a4ce-6a1b-5c22-b3bb-c2404137110a', '2026-27', 'application', 'ED', 'Early Decision I', '2026-11-02', null, 'Binding. Notification ''mid-December'' (no exact date published).', '453a5c9f-0e20-5693-8b25-b3541ceeb626'),
 ('56d16d12-185f-5ef7-ae6f-8d6f55076ba2', 'd5e1a4ce-6a1b-5c22-b3bb-c2404137110a', '2026-27', 'application', 'ED2', 'Early Decision II', '2027-01-04', null, 'Binding. Notification ''early February'' (no exact date published).', '453a5c9f-0e20-5693-8b25-b3541ceeb626'),
 ('e60b93b4-bd88-5021-acd0-fcba2e7aa172', 'd5e1a4ce-6a1b-5c22-b3bb-c2404137110a', '2026-27', 'application', 'RD', 'Regular Decision', '2027-01-04', '2027-04-01', 'Notification ''by April 1''.', '453a5c9f-0e20-5693-8b25-b3541ceeb626');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('d5e1a4ce-6a1b-5c22-b3bb-c2404137110a', 'required_nonnative', 'Not required if you have at least three years of study in a secondary school where the primary language is English (still allowed to submit). Applicants who took ESOL classes may be asked for proof. TOEFL ITP Plus and the IELTS Indicator do not satisfy the requirement. No superscoring (including TOEFL MyBest); report each section from the same test date. InitialView or Duolingo interviews are accepted in addition to test results.', '1ca2c2d3-67d5-5a89-918f-d5cbcd69a13f');
insert into english_requirements (institution_id, status, source_id, test_key, recommended_total, notes)
select 'd5e1a4ce-6a1b-5c22-b3bb-c2404137110a'::uuid, 'required_option', '1ca2c2d3-67d5-5a89-918f-d5cbcd69a13f'::uuid, v.* from (values
 ('TOEFL_IBT', 100, 'Tufts has no score minimums; generally successful applicants have at least 100 on exams before 2026-01-21.'),
 ('TOEFL_IBT_2026', 5.0, 'At least 5.0 for exams on or after 2026-01-21 (typical, not a minimum).'),
 ('IELTS', 7.0, 'Typical, not a minimum.'),
