insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('e05402d5-aed6-59b2-af4b-44efe445bb9f', '2026-27', 'optional', 'The application checklist lists "SAT or ACT Scores" as optional. The 2025-2026 Common Data Set (C8A, Fall 2027) also marks SAT/ACT as "not required for admission, but considered if submitted". The admissions pages do not state the policy in a single sentence.', '5c922395-5d3e-589f-8331-8bcd9289cb73');
insert into application_requirements (institution_id, cycle, platforms, teacher_recs, counselor_rec, notes, source_id) values
 ('e05402d5-aed6-59b2-af4b-44efe445bb9f', '2026-27', array['common_app']::text[], 0, true, 'Checklist: application (activities list and personal statement), high school transcript, and the Secondary School Report / school counselor recommendation. "We do not require teacher recommendations (only a counselor recommendation)." SAT/ACT scores and portfolio or audition materials are optional. The pages reviewed do not state the application fee, a writing supplement, or an interview policy, so those are left blank. ED and ED II applicants must submit a CSS Profile.', '5c922395-5d3e-589f-8331-8bcd9289cb73');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('4fd83562-38d5-5f86-b206-9ee82a993965', 'e05402d5-aed6-59b2-af4b-44efe445bb9f', '2026-27', 'application', 'ED', 'Early Decision I', '2026-11-01', '2026-12-15', 'Binding. Decisions "by December 15"; enrollment deposit due January 15. Need-based aid applications (CSS Profile) due November 15.', '9273f87b-0a75-5b86-a50a-b0d60fd57ae4'),
 ('a44f5802-8534-5f2c-b79f-a9574039b0b8', 'e05402d5-aed6-59b2-af4b-44efe445bb9f', '2026-27', 'application', 'EA', 'Early Action', '2026-11-10', '2027-01-10', 'Non-binding. Decisions "by January 10"; enrollment deposit due May 1. Need-based aid applications due December 15.', '9273f87b-0a75-5b86-a50a-b0d60fd57ae4'),
 ('3876598f-cda5-5149-819e-a15a21ccd591', 'e05402d5-aed6-59b2-af4b-44efe445bb9f', '2026-27', 'application', 'ED2', 'Early Decision II', '2027-01-15', '2027-02-15', 'Binding. Decisions "by February 15"; enrollment deposit due March 1. Need-based aid applications due January 15.', '9273f87b-0a75-5b86-a50a-b0d60fd57ae4'),
 ('445a45d4-affa-5249-a4fd-1d883541ad58', 'e05402d5-aed6-59b2-af4b-44efe445bb9f', '2026-27', 'application', 'RD', 'Regular Decision', '2027-01-15', '2027-04-01', 'Decisions "by April 1" (includes deferred Early Action applicants); enrollment deposit due May 1. Need-based aid applications due February 15. The pages state no entry year; treated as the 2026-27 cycle (Fall 2027 entry).', '9273f87b-0a75-5b86-a50a-b0d60fd57ae4');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('e05402d5-aed6-59b2-af4b-44efe445bb9f', 'required_nonnative', 'Required for non-native English speakers (TOEFL, IELTS, Duolingo English Test or Cambridge C1/C2). Waived with SAT reading/writing 600+ or ACT English 27+, or if the student has studied in a country where English is an official language (contact an admission counselor if the portal does not apply the waiver). The page is undated and does not mention the new 1-6 TOEFL scale.', 'ee1e7024-21df-5c5c-ab57-4dd9f6b86d0d');
