insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, app_fee_usd, notes, source_id) values
 ('03fa17b3-c2b4-5f3a-ae70-24468d33a246', '2026-27', array['uc_app']::text[], '4 Personal Insight Questions (choose 4 of 8)', 0, false, 80, 'Fee is $80 per campus, $95 for international applicants; fee waivers cover up to four campuses but only for U.S. citizens, permanent residents and AB540-eligible applicants. UC does not require or read letters of recommendation at application. The 4 Personal Insight Questions are the only essays (no campus supplement).', '9f265ff9-4ded-5237-91e7-52b430bf829d');
