insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('03fa17b3-c2b4-5f3a-ae70-24468d33a246', 'required_nonnative', 'Required if you studied in the U.S. fewer than three years and received instruction in a language other than English before that. UC Davis lists TOEFL, IELTS, Duolingo, certain AP/IB exams or transferable college English coursework; minimums are the UC-wide ones. UC notes Davis, UCLA and Santa Barbara may require additional English testing after admission.', '4d370b4f-6b35-58d2-974e-731cbbe2b8ad');
