insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('3df39cc8-bdaa-5452-9229-d21e2c26bf31', 'required_nonnative', 'Required if all secondary school was in a country where English is not the language of instruction. Alternatives accepted by UC: AP English Language or Literature 3-5, IB English A SL 6-7 / HL 5-7, ACT English Language Arts 24+, SAT Writing and Language 31+, or a C or better in a UC-transferable college English composition course. Exam must be taken by December of the final year. Individual campuses may set higher minimums.', '7c7a54c9-9ca9-5dd8-be1f-8d08a6582319');
