insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('f698d33c-bb66-5414-82a8-543cf4846078', 'required_nonnative', 'UCSC applies it when less than three years of secondary schooling was in English. Required if all secondary school was in a country where English is not the language of instruction. Alternatives accepted by UC: AP English Language or Literature 3-5, IB English A SL 6-7 / HL 5-7, ACT English Language Arts 24+, SAT Writing and Language 31+, or a C or better in a UC-transferable college English composition course. Exam must be taken by December of the final year. Individual campuses may set higher minimums.', '00d43fcc-18b7-5e03-948d-7dacc46cb1a8');
