 ('TOEFL_IBT', 80, 100, 'UC minimum 80 (tests before Jan 2026). UCLA looks for competitive scores: above 100 with every section above 24.'),
 ('TOEFL_IBT_2026', 4.5, 5.0, 'UC minimum 4.5 (Jan 2026 or later). UCLA looks for 5 or higher with every section 5 or higher.'),
 ('IELTS', 6.5, 7.5, 'UCLA looks for 7.5 or above.'),
 ('DUOLINGO', 115, 135, 'UCLA looks for 135 or higher.')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
select 'ba6f6326-df17-5b28-9055-e105ba1840ee'::uuid, v.* from (values
 ('sat', '4837', 'UCLA is test-blind: SAT/ACT are not considered for admission or scholarships; codes apply only to scores sent after admission.', 'c7357df9-1e4d-547f-ae92-32c179bd0c06'::uuid),
 ('act', '0448', 'UCLA is test-blind; code applies only to scores sent after admission.', 'c7357df9-1e4d-547f-ae92-32c179bd0c06'::uuid),
 ('toefl', null, 'No undergraduate TOEFL code is published. Self-report scores in the UC application; UCLA says a TOEFL report sent to one UC campus reaches all campuses you apply to.', '32f3d373-c684-5288-bffd-29919fde8992'::uuid),
 ('ielts', null, 'No code. UCLA says IELTS results must be sent to each campus you apply to; self-report in the application.', '32f3d373-c684-5288-bffd-29919fde8992'::uuid),
 ('duolingo', null, 'No code. DET scores are sent through the DET portal with your UC Application ID, once per campus.', '32f3d373-c684-5288-bffd-29919fde8992'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid, merit_scholarships, notes, source_id) values
 ('ba6f6326-df17-5b28-9055-e105ba1840ee', '2023-2024', 15729, 53331, 18960, 1680, 6798, 41373, 'none', false, false, 'College Scorecard (IPEDS 2023-24): tuition includes required fees; on-campus cost of attendance.; UCLA''s admissions site says it does not award scholarships or financial aid to undergraduates who are not U.S. citizens or permanent residents; admitted internationals must show funds (about $80,739 minimum for fall 2026 entrants). UCLA''s financial aid site says internationals may be eligible only for outside scholarships, private loans and short-term loans.', '561e0e9a-59f0-5bae-aa16-01bc46d4144b');
