insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('46975e20-28ac-5ece-bc3c-dd728fead7c0', '2026-27', 'required', 'Official SAT or ACT scores are required of all first-year applicants; there is no test-optional pathway. UGA superscores both tests. Minimums set by the Board of Regents: SAT EBRW 480 and Math 440, or ACT English or Reading 17 and Math 17.', '31cb54fc-65f8-5262-b793-611064160e77');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('46975e20-28ac-5ece-bc3c-dd728fead7c0', '2026-27', '{}'::text[], 85, 'First-year application fee is $70 for US citizens and $85 for international students. Letters of recommendation are optional (one is highly recommended). International students should choose ''Do not self-report grades'' and send final English-translated transcripts; UGA recalculates the GPA.', '0cfa6b88-d6e5-5f1a-8c48-f33150806666');
