insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('3e512b67-e6f8-5a28-ac52-6d439854761e', '2026-27', array['common_app']::text[], 85, 'Complete Common App including the UMass questions; fee is $85 for international applicants and cannot be waived. A letter of recommendation is listed as required (number of recommenders not stated). An optional third-party unscripted interview (e.g. InitialView) may be submitted by international students. UMass does not offer early decision.', 'a8195492-1fa3-591b-a882-ceb351b8b54f');
