insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('1532a872-1f5b-5818-af57-e857d8bb7a85', '2026-27', 'optional', 'International first-year students can apply under the Test Optional plan without SAT/ACT scores (select ''Test Optional'' on the application) for Early Action I, Early Action II and Regular Decision. Applicants who do submit scores may self-report them but must send official scores before orientation. Test-optional applicants can still qualify for merit scholarships. The page says the most competitive test-optional applicants have a recalculated high school GPA of 3.2 or higher.', '87197554-1e75-5858-9dcd-196f34c23004');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('1532a872-1f5b-5818-af57-e857d8bb7a85', '2026-27', array['common_app','own']::text[], 60, 'Apply with either the UMass Boston Application or the Common App. Required: $60 fee, official high school record/leaving certificate or graduation exam results (certified English translation; country-specific document lists apply), one academic recommendation letter from a school counselor and/or teacher, and a personal essay of about 500 words. The essay is also used for Honors College and scholarship consideration. Official English test scores must come from the testing agency.', '8e92df2d-dc80-5f9b-a28d-99eacf9be17f');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('92dfb3c1-422d-50ed-965e-950b60ee3363', '1532a872-1f5b-5818-af57-e857d8bb7a85', '2026-27', 'application', 'EA', 'Early Action I (fall 2027 entry)', '2026-11-01', 'The page prints no year; taken as the current cycle. Test-optional applicants may use this round.', '8e92df2d-dc80-5f9b-a28d-99eacf9be17f'),
 ('96c453de-554a-538b-8cd0-279a012692f5', '1532a872-1f5b-5818-af57-e857d8bb7a85', '2026-27', 'application', 'EA', 'Early Action II (fall 2027 entry)', '2027-01-01', null, '8e92df2d-dc80-5f9b-a28d-99eacf9be17f'),
 ('2e581fc2-e5ef-583a-b1db-29c7b05468cc', '1532a872-1f5b-5818-af57-e857d8bb7a85', '2026-27', 'application', 'RD', 'Regular Decision (fall 2027 entry)', '2027-02-15', null, '8e92df2d-dc80-5f9b-a28d-99eacf9be17f');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('1532a872-1f5b-5818-af57-e857d8bb7a85', 'required_nonnative', 'Required for students whose native language is not English and who have not completed an English-based curriculum. Students from listed countries (e.g. Australia, Canada except Quebec, Ireland, Jamaica, Kenya, Nigeria, Singapore, Hong Kong, New Zealand) are exempt from the English proficiency test. Alternatives to TOEFL/IELTS/Duolingo: SAT EBRW 480+ or ACT English plus Reading totaling 34+. Self-reported scores are not accepted for the English requirement. Provisional admission: an applicant who meets all other criteria but misses the TOEFL/IELTS minimum may be provisionally admitted and referred to the University Preparation ESL program; provisional admission is not offered for nursing, engineering or management applicants.', '8e92df2d-dc80-5f9b-a28d-99eacf9be17f');
