insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('cda0864c-0713-5272-a8ef-41aead30c138', '2026-27', 'optional', 'SAT/ACT optional with a weighted GPA of 2.8 or above (4.0 scale). Students below 2.8 must submit ACT 17+ or SAT 930+. Stated for 2026-27 and beyond. Scores are one factor among many.', '639185cd-ed50-574b-a803-2ea15aaf7127');
insert into application_requirements (institution_id, cycle, platforms, teacher_recs, counselor_rec, app_fee_usd, notes, source_id) values
 ('cda0864c-0713-5272-a8ef-41aead30c138', '2026-27', array['common_app']::text[], 1, true, 85, 'Fee waiver via school counselor. One recommendation from a core-academic teacher; international page also requires a secondary school official report (not from a private counseling company/agent) and official transcript with English translation. A personal essay is required. Fee, teacher letter and counselor report as listed on the international first-year page.', 'b8236fc6-a5cc-5c80-8277-26c543c05c01');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('0d5586a4-50dc-5039-aec6-f7b8cef36158', 'cda0864c-0713-5272-a8ef-41aead30c138', '2026-27', 'application', 'EA', 'Early Action (non-binding)', '2026-10-15', '2027-02-15', 'Decisions by Dec 20 for North Carolina residents, by Feb 15 for all others. Supporting materials and test scores due Nov 7.', 'b8236fc6-a5cc-5c80-8277-26c543c05c01'),
 ('a379cb67-c9d6-5f5f-a066-fcbebfd08088', 'cda0864c-0713-5272-a8ef-41aead30c138', '2026-27', 'application', 'RD', 'Regular Decision', '2027-01-15', '2027-03-31', 'Supporting materials due Feb 15 per the international page (the domestic first-year page says Feb 21).', 'b8236fc6-a5cc-5c80-8277-26c543c05c01'),
 ('b21e6e46-8f76-59e0-ba47-f149b819396e', 'cda0864c-0713-5272-a8ef-41aead30c138', '2026-27', 'deposit', null, 'Enrollment confirmation (EA and RD)', '2027-05-01', null, null, 'b8236fc6-a5cc-5c80-8277-26c543c05c01');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('cda0864c-0713-5272-a8ef-41aead30c138', 'required_nonnative', 'Required for non-US citizens/non-permanent residents. Waived if you will have lived in a country where English is the primary language, or attended a school with English as the primary language of instruction, for at least the last four years (including the current year) before enrolling. English-course grades and SAT/ACT do not qualify.', 'ae6fc595-51ff-5e60-b0cd-0508e0690c89');
