insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('000e7378-5194-59a3-9fce-dc985403e2f0', '2023-2024', 12232, 11774, 4583, 11, 67, 'Baseline from IPEDS (fall 2023 entering class). UNLV''s 2025-26 and 2024-25 Common Data Set PDFs on it.unlv.edu have no readable text layer for the filled-in values (only the blank form text extracts), so the IPEDS baseline is used; GPA, residency splits and factors are not added. Undergrad enrollment (25,794) and nonresident undergrads (446) are IPEDS fall 2023 (EF2023A); student-faculty ratio 19 to 1 is College Navigator (fall 2024). College Navigator also shows fall 2024: 12,730 applicants, 96% admitted.', 'cebcbe01-5de3-568f-bd46-7bf565b37c2b', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
