insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, room_board_usd, books_usd, other_usd, intl_aid_policy, merit_scholarships, notes, source_id) values
 ('000e7378-5194-59a3-9fce-dc985403e2f0', '2026-2027', 11231, 31420, 31710, 13448, 1290, 4664, 'merit_only', true, 'UNLV cost page (2026-27, 15 credits, two semesters): the tuition figures already include required fees and a one-time $200 new-student fee; international (F-1) $31,710 includes a $145-per-semester international fee; mandatory health insurance for international students is estimated separately. room_board = on-campus housing $7,424 + food $6,024; other_usd = transportation $1,360 + miscellaneous $3,304. Estimated nonresident total cost living on campus $50,284.; Admitted international undergraduates may be considered for merit-based scholarships of $5,000-$7,000 per year (once a year, fall entry only; must be admitted before the priority deadline and complete UNLV''s Alternative Need Form). No need-based aid for international students is described, so that is left unconfirmed.', '2ba3f323-97b6-5a5c-88a6-cc40cb1fc1e8');
