insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('27ac595e-8dde-5e8c-8670-a6f952caa83b', '2026-27', 'optional', 'USC continues its test-optional policy for first-year applicants to the 2027-28 academic year. Scores, if sent, must be official (self-reported scores are not accepted). International applicants who use the SAT or ACT to show English proficiency have those scores assessed for both proficiency and admission.', '3e0b0b0b-d30f-53ab-9a79-f6447c4e6237');
insert into application_requirements (institution_id, cycle, platforms, teacher_recs, interview, fee_waiver, css_profile_required, midyear_report, notes, source_id) values
 ('27ac595e-8dde-5e8c-8670-a6f952caa83b', '2026-27', array['common_app']::text[], 1, 'optional_informational', true, true, true, 'One letter of recommendation is required, from either a school counselor or a teacher; some majors require more. Some majors need a portfolio, resume, writing sample or audition. USC does not conduct admission interviews or track demonstrated interest; Duolingo, InitialView and Vericant video interviews are optional English-proficiency supplements only. International applicants must submit the Financial Statement of Personal or Family Support. CSS Profile and FAFSA are for need-based aid applicants (US citizens and eligible non-citizens). Application fee amount not found on the pages opened.', 'eff8ca13-726f-5e1c-ae66-1f8d5605bdf1');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('e10f00df-45f2-51cd-a98d-23f98cbb3dce', '27ac595e-8dde-5e8c-8670-a6f952caa83b', '2026-27', 'application', 'ED', 'Early Decision (most majors)', '2026-11-01', null, 'Binding. Decision by mid-December (applicants may instead be offered deferral to Regular Decision). Not offered for Kaufman School of Dance, School of Dramatic Arts or Thornton School of Music. Page lists month and day only; aid deadline on the same page is dated 2026.', 'eff8ca13-726f-5e1c-ae66-1f8d5605bdf1'),
 ('86f1caa3-5e72-5d3d-bc03-c83c7a3cdae8', '27ac595e-8dde-5e8c-8670-a6f952caa83b', '2026-27', 'application', 'EA', 'Early Action (most majors)', '2026-11-01', null, 'Non-binding, non-restrictive. The first-year page says decisions come in late January; the Deadline FAQs say mid-January. Not offered for the performing arts schools above.', 'eff8ca13-726f-5e1c-ae66-1f8d5605bdf1'),
 ('68ae6975-d672-597f-b544-535320a912ca', '27ac595e-8dde-5e8c-8670-a6f952caa83b', '2026-27', 'application', 'RD', 'Regular Decision (performing arts majors)', '2026-12-01', '2027-04-01', 'Only deadline for Kaufman School of Dance, School of Dramatic Arts and Thornton School of Music.', 'eff8ca13-726f-5e1c-ae66-1f8d5605bdf1'),
 ('78b5a4b2-2f8b-5e8c-a177-881067ee689c', '27ac595e-8dde-5e8c-8670-a6f952caa83b', '2026-27', 'application', 'RD', 'Regular Decision (most majors)', '2027-01-10', '2027-04-01', 'Notification by April 1.', 'eff8ca13-726f-5e1c-ae66-1f8d5605bdf1'),
 ('8dbf1e52-325a-5b4d-b0a8-0141632dfebe', '27ac595e-8dde-5e8c-8670-a6f952caa83b', '2026-27', 'financial_aid', 'ED', 'Financial aid deadline - Early Decision', '2026-11-01', null, 'FAFSA and CSS Profile (US citizens/eligible non-citizens).', 'eff8ca13-726f-5e1c-ae66-1f8d5605bdf1'),
 ('6fab57e9-76bc-5bcd-bc3c-0b4b5f612d37', '27ac595e-8dde-5e8c-8670-a6f952caa83b', '2026-27', 'financial_aid', 'EA', 'Financial aid deadline - Early Action', '2026-11-15', null, null, 'eff8ca13-726f-5e1c-ae66-1f8d5605bdf1'),
 ('0a1c5906-f3a9-5739-8b46-55db19c6c4e2', '27ac595e-8dde-5e8c-8670-a6f952caa83b', '2026-27', 'financial_aid', 'RD', 'Financial aid deadline - Regular Decision', '2027-02-03', null, null, 'eff8ca13-726f-5e1c-ae66-1f8d5605bdf1');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('27ac595e-8dde-5e8c-8670-a6f952caa83b', 'required_nonnative', 'USC says it does not grant waivers or exceptions, including for applicants already living in the US. An SAT Evidence-Based Reading and Writing score of 650+ or ACT English 27+ also satisfies the requirement. Duolingo is for applicants who cannot sit for another approved exam; Duolingo-only admits must take USC''s International Student Exam on arrival. Scores are due within two weeks of the application deadline. TOEFL ITP Plus (China) is not accepted.', '3e0b0b0b-d30f-53ab-9a79-f6447c4e6237');
