insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, pct_submit_sat, pct_submit_act, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id) values
 ('839eb235-b785-5929-9260-730c382b6cd3', '2025-2026', 12357, 12350, 4569, 301, 295, 11928, 11928, 128, 127, 1.99, 2.82, 3.32, 83.44, '{"4.0": 0.16, "3.75-3.99": 19.22, "3.50-3.74": 23.07, "3.25-3.49": 21.24, "3.00-3.24": 17.65, "2.50-2.99": 11.36, "2.0-2.49": 4.64, "1.0-1.99": 2.44}'::jsonb, 'CDS C1 (fall 2025 first-years): 12,350 of 12,357 applicants admitted (99.9%); international 295 of 301 admitted, 190 enrolled. GPA bands are the ''all enrolled students'' column of C11 (a further 0.24% had GPA below 1.0). Only 91 enrollees submitted SAT and 129 ACT scores (C9), so the score percentiles describe a very small, self-selected group. The CDS C7 importance marks could not be read from the PDF text, so admission factors are omitted. Undergraduate enrollment 22,223 is CDS B1 total undergraduates; 843 is degree-seeking nonresident undergraduates (B2). Student-faculty ratio 21:1 is from IPEDS College Navigator.', '9bf484cd-6913-5249-9a82-5c4913afb007');
