insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('839eb235-b785-5929-9260-730c382b6cd3', '2026-27', 'flexible', 'International applicants must submit an entrance exam; SAT 1070 (with 480 reading) or ACT 23 (with 19 English), TOEFL iBT 61 or PTE 44 each satisfy it (IELTS not accepted). Domestic assured admission by class rank and SAT/ACT: top 25% no minimum; 2nd 25% SAT 920/ACT 19; 3rd 25% 970/20; 4th 25% 1010/21 (other pathways exist).', '6a22f8df-7faa-5d3a-a143-3880178d6165');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('839eb235-b785-5929-9260-730c382b6cd3', '2026-27', array['own']::text[], 65, 'Apply through ApplyTexas (''own''). The $65 fee is for international applicants (no application fee for domestic applicants, no essay requirement). International first-year applicants need a cumulative average equivalent to 3.0 on a 4.0 scale plus the test scores above, official transcripts sent directly by the school (certified English translation if needed) and a Certification of Financial Resources form before an I-20 is issued. Admission to UTEP does not assure admission into the professional colleges or programs with secondary admission requirements.', 'e7ada9b6-7ed2-53d4-aba4-b29fd269f925');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('d8ddbef0-5956-5994-8722-ab8dcc75e7ed', '839eb235-b785-5929-9260-730c382b6cd3', '2026-27', 'priority', 'ROLLING', 'Fall priority date / international document due date (fall 2027 entry)', '2027-05-01', 'CDS C14 lists a fall priority date of 5/1 and an archived UTEP catalog page lists May 1 as the fall international document due date; current admissions pages print no international deadline, so confirm with UTEP. Applications are accepted year-round and decisions are rolling (CDS C16). Files completed after the due date roll to the next semester.', '41dd3331-6d44-5b01-8c6b-0dd79408c916');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('839eb235-b785-5929-9260-730c382b6cd3', 'required_nonnative', 'Waived for students from countries where English is the native or official language of instruction, with SAT reading 480 or ACT English 19, or with a C or better in a freshman-level reading/writing-intensive course at another U.S. institution. Completing UTEP''s English Language Institute also meets the requirement. Admitted students who took the TOEFL below 600 or PTE below 68 must take the ACCUPLACER ESL test and may be placed in ESOL courses.', 'e7ada9b6-7ed2-53d4-aba4-b29fd269f925');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, notes)
select '839eb235-b785-5929-9260-730c382b6cd3'::uuid, '6a22f8df-7faa-5d3a-a143-3880178d6165'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 61, 'Or 500 on UTEP''s institutional paper-based TOEFL; the current page does not mention the new 1-6 scale, so no TOEFL_IBT_2026 minimum is listed.'),
 ('IELTS', 'not_accepted', null, 'UTEP does not accept IELTS scores for admission.'),
 ('PTE', 'required_option', 44, null)) v;
