insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, pct_submit_sat, pct_submit_act, notes, source_id) values
 ('c5aed17b-a2ae-55b9-92f7-a6d1c4954772', '2024-2025', 25422, 22063, 5980, 458, 442, 23871, 20828, 1093, 793, 61.0, 7.0, 'CDS 2024-2025 (fall 2024 first-years), the newest CDS listed on UTSA''s Institutional Research page (a 2025-26 file was not available). C1: 25,422 applicants, 22,063 admitted, 5,980 enrolled. International admit rate 96.5% (442 of 458), 104 enrolled. UTSA left high school GPA (C11/C12) blank, so GPA fields are omitted; 16% of enrollees were in the top tenth and 55% in the top quarter of their class (C10). Undergraduate enrollment 31,127 is CDS B1 total undergraduates; 427 is degree-seeking nonresident undergraduates (B2). Student-faculty ratio 23.8 is CDS I-2 (fall 2024).', 'fb17b936-a971-56aa-b706-5aa6860c7794');
