insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('c5aed17b-a2ae-55b9-92f7-a6d1c4954772', '2026-27', 'optional', 'SAT/ACT are optional for admission; scores are reviewed only if submitted and may help qualify for guaranteed admission (top 25% of class: no minimum; 2nd 25%: SAT 1170 or ACT 24). Everyone else gets a holistic review. International freshman applicants: SAT/ACT optional.', '0ca85afe-4e89-5b7f-9a2d-246ae24e1ca2');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('c5aed17b-a2ae-55b9-92f7-a6d1c4954772', '2026-27', array['common_app','own']::text[], 75, 'Apply through ApplyTexas (''own'') or the Common App, one application per term. The $75 fee is non-refundable and fee waivers are not available to international freshmen. International freshmen need the equivalent of a U.S. high school diploma, a minimum 2.5 GPA (4.0 scale) and English proficiency; official transcripts need certified English translations. For holistic review an essay and two recommendations are highly suggested. Some majors have extra requirements; others are admitted into University College ''academic studies'' first.', '256e94db-c654-53a6-9e6d-42ba45e71add');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('c7431100-d494-572e-a6fe-0d97db002240', 'c5aed17b-a2ae-55b9-92f7-a6d1c4954772', '2026-27', 'priority', 'Priority freshman deadline and Distinguished Presidential Scholarship admit-by date (fall 2027)', '2027-01-15', 'Fall freshmen admitted by January 15 get automatic scholarship consideration (up to $24,000 over four years).', '0ca85afe-4e89-5b7f-9a2d-246ae24e1ca2'),
 ('bc842cc0-1b33-5a38-a8f8-334928f62b62', 'c5aed17b-a2ae-55b9-92f7-a6d1c4954772', '2026-27', 'application', 'International freshman deadline: submit application (fall 2027)', '2027-06-01', 'All fees, transcripts and test scores must be received by 5:00 p.m. CT. Missing documents may still be submitted by June 15 (domestic freshman deadline is the same June 1 / June 15).', '0ca85afe-4e89-5b7f-9a2d-246ae24e1ca2'),
 ('ac1e04bf-b8bc-5c7b-873e-8648ae87922c', 'c5aed17b-a2ae-55b9-92f7-a6d1c4954772', '2026-27', 'other', 'International freshman: last day to submit missing documents (fall 2027)', '2027-06-15', null, '0ca85afe-4e89-5b7f-9a2d-246ae24e1ca2');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('c5aed17b-a2ae-55b9-92f7-a6d1c4954772', 'required_nonnative', 'Waived for graduates of a U.S. high school or listed English-speaking country with two full years of standard English courses; B- or better in college English Composition I; SAT EBRW 500+ or ACT English 21+; a bachelor''s degree or higher from the U.S. or a listed English-speaking country; or citizens of listed countries (e.g. Australia, Canada except Quebec, Ireland, New Zealand, Nigeria, Singapore, South Africa, United Kingdom). Scores are judged on the scale in effect when the test was taken.', 'e59779af-6608-546b-866a-be9b1aadf0b5');
