insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('181f6451-d7cc-54ec-9f09-69615eb6b7fb', '2026-27', 'optional', 'Vassar does not require SAT/ACT; applicants declare in the applicant portal whether to include scores (declaration deadlines: ED I Nov 22, ED II and RD Jan 8). Vassar superscores and accepts self-reported scores; enrolling students must send official reports.', '3c0a7ffd-69e1-537a-8ee8-63291fc3591d');
