insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('37250efa-f14d-584e-ad28-0d82b57eed74', '2026-27', 'optional', 'All first-year applicants, including international applicants and those seeking scholarships, get test-optional review regardless of GPA. Exceptions: scores are required for the Honors College Guaranteed Admission Programs; the international page also says SAT or GRE scores are required for pre-nursing/nursing applicants and SAT or ACT for mechanical engineering applicants.', 'c098d747-4389-5377-95ef-0f8070238462');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('37250efa-f14d-584e-ad28-0d82b57eed74', '2026-27', array['common_app']::text[], 75, 'International first-year applicants must use the Common App ($75 state-required fee, nonrefundable, paid by credit card). Essays are required of all 2027 applicants; at least one recommendation is preferred. Official transcripts in the original language with English translation (notarized copies not accepted), plus passport/visa documents. Minimum 20 academic units on the Monroe Park Campus. School of the Arts applicants submit supplemental materials. Honors College needs an additional application (competitive: 3.5 GPA and SAT 1330 or ACT 29).', 'c098d747-4389-5377-95ef-0f8070238462');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('f27a3d7c-3fe4-5570-887d-a3d91a25747e', '37250efa-f14d-584e-ad28-0d82b57eed74', '2026-27', 'scholarship', null, 'First-year scholarship deadline (fall 2027 entry)', '2026-11-01', null, 'Common App plus official transcript received by Nov. 1 for university-level scholarships (Provost, Deans''); international applicants who apply by Nov. 1 are also considered. Honors College Guaranteed Admission Programs are also due Nov. 1.', '984e22c0-2a27-5649-818e-c660c2dc9e44'),
 ('262bcf26-019d-54f1-a9f4-c17907a775cd', '37250efa-f14d-584e-ad28-0d82b57eed74', '2026-27', 'application', 'RD', 'First-year regular decision deadline (fall 2027 entry)', '2027-01-15', '2027-04-01', 'Complete applications by Jan. 15 are guaranteed a decision by April 1. Guaranteed University Admission (GPA 3.5+) uses the same date; the School of the Arts is not eligible for it.', '984e22c0-2a27-5649-818e-c660c2dc9e44'),
 ('ed5e445e-4e04-5691-91e5-8c9e86ca76cb', '37250efa-f14d-584e-ad28-0d82b57eed74', '2026-27', 'deposit', null, 'Response deadline for first-year offers made by April 1', '2027-05-01', null, 'If accepted after April 1, respond within two weeks.', '984e22c0-2a27-5649-818e-c660c2dc9e44');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('37250efa-f14d-584e-ad28-0d82b57eed74', 'required_nonnative', 'Waived with: IB English A1 grade 5+; grades 9-12 at a US/US-accredited high school with a C or better in English (or WIDA 5.0); GCSE/O-level English language; graduation from an American high school abroad or IB/A-level school with a C or better in English; high school in a listed English-speaking country (UK, Ireland, Canada except Quebec, Australia, New Zealand, Singapore, South Africa, etc.); six college English composition semester hours (C or better); or completing VCU''s English Language Program. Other accepted proofs: SAT EBRW 500+, ACT English 16+, Gaokao English 125/150, CBSE English 80%, CET-6 500. Test scores are valid two years from the test date. VCU''s TOEFL code is 5570.', 'c098d747-4389-5377-95ef-0f8070238462');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
