insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('1ce62010-20c1-5878-a296-f8ae611cde9b', '2026-27', 'optional', 'Test-optional through the 2026-27 admission campaign (class of 2031). Official or self-reported scores accepted; SAT/ACT superscored across dates. Scores reported by Nov 10 (ED I/EA) or Jan 31 (ED II/RD) are considered. Homeschooled applicants (more than one full year) must submit scores.', '7f6c1e32-5d1b-5241-a304-c0e0b0a3aaa1');
