insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, pct_submit_sat, pct_submit_act, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id) values
 ('f4125e0a-3041-53dd-a4c4-4e8d97917c73', '2025-2026', 26403, 22732, 4420, 656, 590, 15845, 13466, 9902, 8676, 6.24, 1.11, 3.46, 99.23, '{"4.0": 3.6, "3.75-3.99": 25.03, "3.50-3.74": 21.39, "3.25-3.49": 19.24, "3.00-3.24": 17.12, "2.50-2.99": 13.11, "2.0-2.49": 0.5, "1.0-1.99": 0.0}'::jsonb, 'CDS fall 2025 first-year class (C1). The CDS enrollment tables (B1/B2) are WSU systemwide: 21,400 undergraduates including the Pullman, Vancouver, Tri-Cities, Everett and Global campuses, of whom 483 are nonresident (international) students; the student-faculty ratio is 14:1. The CDS left the SAT/ACT percentile cells blank, so no score ranges are loaded. Only 6.24% of enrollees submitted SAT and 1.11% ACT. No early decision or early action; no waitlist policy.', '944fc8db-66e4-5279-8679-6aa534a28137');
