insert into cost_aid (institution_id, year, tuition_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_need_aid, meets_full_need, merit_scholarships, notes, source_id) values
 ('29b755b7-4fc7-561e-b2a5-e257d04e010d', '2023-2024', 69594, 23338, 1357, 3706, 92523, true, true, true, 'College Scorecard (IPEDS 2023-24): tuition includes required fees; on-campus cost of attendance.; Page states WashU meets 100 percent of demonstrated need for all admitted undergraduates; international applicants are eligible for aid only if they apply for it during the admission process. The page does not say whether admission is need-blind or need-aware for international applicants. School Scholarships (up to full tuition, four-year) need no separate application; Signature Scholar Programs need a December 16, 2026 submission for priority.', 'b8fa89c0-31c3-520d-a6ae-11e4145c5b9d');
