insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('1ef7bed2-2e21-5878-87fb-f47c4cd20bec', '2026-27', 'optional', 'The international checklist asks for an SAT/ACT score or test-optional documents (one essay, an activities list and an optional letter of recommendation). Merit scholarships are considered on GPA if no score is submitted.', 'c9c45090-2a4b-5e94-a283-579a1929a136');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('1ef7bed2-2e21-5878-87fb-f47c4cd20bec', '2026-27', array['own']::text[], 25, 'Complete the university undergraduate application with the $25 fee. Documents: transcripts translated into English by an accredited evaluation agency plus original-language transcripts, course descriptions (for transfer credit), signed statement of financial support with a bank statement (not older than six months), passport/photo proof of citizenship and visa documents. $50 enrollment deposit, nonrefundable after May 1 for first-year students. The page does not mention the Common App.', 'c9c45090-2a4b-5e94-a283-579a1929a136');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('06b1debd-3e27-5d1e-a044-3b7a3610273d', '1ef7bed2-2e21-5878-87fb-f47c4cd20bec', '2026-27', 'application', 'ROLLING', 'International fall application deadline (fall 2027)', '2027-08-01', 'Winter (January) deadline is Dec 1 and spring/summer is April 1. The page gives month/day only; the year is assumed for fall 2027. CDS C14 also lists Aug 1 as the first-year closing date.', 'c9c45090-2a4b-5e94-a283-579a1929a136'),
 ('90aa4007-8449-5279-b7ac-e6ecfcf05fea', '1ef7bed2-2e21-5878-87fb-f47c4cd20bec', '2026-27', 'scholarship', null, 'Priority date for maximum merit scholarship consideration (fall 2027)', '2027-02-01', 'The scholarship pages give Feb 1, 2027 (priority) and April 1, 2027 (final). The international checklist page separately says to submit all documents by December 1 for merit scholarship consideration; confirm which applies with Admissions.', '9c5dba6c-c96a-5754-bede-b1c9326c85e4'),
 ('d92d8684-1aef-5379-97a3-251b756c2af5', '1ef7bed2-2e21-5878-87fb-f47c4cd20bec', '2026-27', 'deposit', null, 'Enrollment deposit becomes nonrefundable ($50)', '2027-05-01', 'Deposit is due when you accept the offer.', 'c9c45090-2a4b-5e94-a283-579a1929a136');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('1ef7bed2-2e21-5878-87fb-f47c4cd20bec', 'required_nonnative', 'Exempt if your native language is English, you completed all secondary/postsecondary education in the US, Canada or another listed English-speaking country (US high school students need at least two years), you hold a US associate degree, or you have transfer credit equivalent to WSU''s composition requirements with a 2.0 GPA. Completing the highest level of WSU''s English Language Institute also satisfies the requirement. Test results must be no more than two years old and must be sent by the testing agency (institution code 1898). TOEFL SuperScore is not accepted.', '964c5066-6720-5391-9192-09aeffbaec29');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '1ef7bed2-2e21-5878-87fb-f47c4cd20bec'::uuid, 'required_option', '964c5066-6720-5391-9192-09aeffbaec29'::uuid, v.* from (values
 ('TOEFL_IBT', 79, 'Exams taken before January 21, 2026.'),
 ('TOEFL_IBT_2026', 4.5, 'Exams taken on or after January 21, 2026. The page lists this value without naming the 1-6 scale.'),
 ('IELTS', 6.5, 'Page says scores of 6.5 or higher.'),
 ('DUOLINGO', 110, null)) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
