insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, intl_aid_policy, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, merit_separate_app, notes, source_id) values
 ('1ef7bed2-2e21-5878-87fb-f47c4cd20bec', '2026-2027', 14188, 32498, 32498, 2298, 12844, 1370, 'merit_only', 287, 10539, false, true, false, 'CDS G1 first-year 2026-27 (CDS lists the same rate for nonresident and international; tuition varies by program for about 78% of undergraduates). CDS H6: 287 nonresidents received institutional aid, average $10,539 (total $3,024,685).; No citizenship needed for admission or merit awards; all incoming students are considered automatically. Fall 2027 first-year awards: Warrior Award $6,500 per year, Gold Award $4,500 per year, Green Award up to $2,500 per year, each for four years (3.0 GPA and full-time enrollment to keep). Federal aid is for US citizens and permanent residents only. CDS H6 boxes show both need-based and non-need-based institutional aid for nonresidents, but Wayne State''s pages describe only merit awards.', '8d4a906e-2f31-5830-9512-d16688316018');
