insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('f883d264-3603-549b-b89e-3e5910ec3fa4', '2026-27', 'optional', 'Wellesley states it will continue to be test optional for applicants entering in fall 2027. The 2025-26 CDS (C8A) also lists SAT/ACT as not required but considered if submitted. NOTE: wellesley.edu returns HTTP 403 to automated fetches, so the live pages were read only through search-extracted text; recheck the page before relying on exact wording.', '410b5215-5a69-5942-8e4b-39a536df8080');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, app_fee_usd, notes, source_id) values
 ('f883d264-3603-549b-b89e-3e5910ec3fa4', '2026-27', array['common_app','coalition','questbridge']::text[], true, 2, true, 0, 'Personal essay (250-650 words) plus a shorter Wellesley-specific writing supplement. Two teacher recommendations and the counselor School Report. Application fee: the 2025-26 CDS (C13) answers ''No'' to having an application fee. Interview policy and CSS Profile requirement not confirmed. Wellesley is a women''s college.', '410b5215-5a69-5942-8e4b-39a536df8080');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('cdc3198e-ffc2-5885-99ef-a2b2f06f7efa', 'f883d264-3603-549b-b89e-3e5910ec3fa4', '2026-27', 'application', 'ED', 'Early Decision I', '2026-11-01', 'Decision mid-December (no exact date published); enrollment deposit due early January. Dates read via search-extracted page text (site blocks automated fetch); verify.', '410b5215-5a69-5942-8e4b-39a536df8080'),
 ('395b53d4-1b98-5f68-8c08-6d95eb3c021e', 'f883d264-3603-549b-b89e-3e5910ec3fa4', '2026-27', 'application', 'ED2', 'Early Decision II', '2027-01-05', 'Binding. Decision mid-February; deposit due by late February. Date read via search-extracted page text; verify.', '410b5215-5a69-5942-8e4b-39a536df8080'),
 ('b3bd5886-153b-53f4-af3a-4687ab42fa10', 'f883d264-3603-549b-b89e-3e5910ec3fa4', '2026-27', 'application', 'RD', 'Regular Decision', '2027-01-08', 'Decision late March (no exact date published); reply by May 1. Date read via search-extracted page text; verify.', '410b5215-5a69-5942-8e4b-39a536df8080');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('f883d264-3603-549b-b89e-3e5910ec3fa4', 'recommended', 'No English proficiency exam is required. Strongly recommended if English is not your native language and you have studied in an English-medium curriculum for fewer than four years. No minimum scores were published on the pages found.', '241c66f5-9e40-5e12-9173-0f66285554c2');
