insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('579eb60f-c4e2-5846-86cd-0a14de0f5f9b', '2026-27', 'optional', 'Test scores are optional for an admissions decision, though a few majors and scholarships require them; superscoring applies. Climb Higher Level 1 needs ACT 30 / SAT 1360 plus a 3.8 GPA.', '85fa83a2-d6af-5a2f-b6b3-7416813cb84d');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('579eb60f-c4e2-5846-86cd-0a14de0f5f9b', '2026-27', array['common_app','own']::text[], 75, 'International fee $75 (WV residents $20, out-of-state $65). Freshman applicants need a converted GPA of at least 2.5 on a 4.0 scale; some majors need higher GPAs for direct entry. Unofficial transcripts are enough to apply; no essays or recommendations are required (first-time freshman page). Rolling admissions.', '146b66b5-0e5d-5a3e-9bd4-d3505758288c');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('26462be0-ef67-5333-833f-ed870e4cbd4f', '579eb60f-c4e2-5846-86cd-0a14de0f5f9b', '2026-27', 'application', 'ROLLING', 'International fall application deadline (''apply by''); all documents due July 1', '2027-06-01', 'The international page lists Fall: apply by June 1, all documents by July 1, without printing a year; taken as fall 2027. Spring: Oct. 1 / Nov. 1. Domestic first-time freshman deadline is Aug. 1 (fall), Dec. 1 (spring); the page encourages early application because some majors are selective or capacity-limited.', '146b66b5-0e5d-5a3e-9bd4-d3505758288c');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('579eb60f-c4e2-5846-86cd-0a14de0f5f9b', 'required_nonnative', 'Exempt: citizens of listed countries (e.g. Australia, Canada, India, Nigeria, Pakistan, UK, Ghana, Kenya, Nepal, South Africa), IB Diploma holders, GCSE/GCE English A-C (or 4-9), 24+ transferable credits in a qualifying country, or students meeting academic admission while pursuing/earning a U.S. high school diploma. SAT EBRW 570 or ACT English 24 are also accepted. WVU does not accept expired scores, General IELTS or institutional TOEFL (ITP); WVU can verify scores directly so official reports are often unnecessary.', 'b6cd67a0-e63f-5549-8eab-654277dc46d6');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
