insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('2c4d6cbd-6838-5c12-ac11-2a3b974e8f7c', '2026-27', 'optional', 'SAT/ACT scores are completely optional; W&M does not require them. Forty percent of the Class of 2029 applied test-optional.', 'e3b59768-119e-5339-893c-a75e670567f9');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('2c4d6cbd-6838-5c12-ac11-2a3b974e8f7c', '2026-27', array['common_app']::text[], 75, 'Checklist lists the Common App, high school transcript, essay and recommendation letters; the exact number of teacher recommendations and supplemental essays was not stated on the pages read. $75 non-refundable fee with a fee-waiver request option. Supplemental materials (transcripts, scores, recommendations) may arrive after the deadline.', '902c2e0c-e857-588b-9f39-92fb04c58182');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('828b4859-b8ef-5237-bea9-4ee3a0f4392d', '2c4d6cbd-6838-5c12-ac11-2a3b974e8f7c', '2026-27', 'application', 'ED', 'Early Decision I (binding)', '2026-11-01', null, 'Decision early December (no exact date published); enrollment deposit due Jan 5; FAFSA and CSS Profile priority Nov 15, final Dec 12.', 'ddd11abb-0393-5735-8680-655a0cffbc28'),
 ('3d8c168b-3d03-582c-97c2-6bc05c0de964', '2c4d6cbd-6838-5c12-ac11-2a3b974e8f7c', '2026-27', 'application', 'ED2', 'Early Decision II (binding)', '2027-01-05', null, 'Decision early February (no exact date published); enrollment deposit due Feb 15; FAFSA and CSS Profile priority Jan 15, final Mar 1.', 'ddd11abb-0393-5735-8680-655a0cffbc28'),
 ('caa873f8-c7bb-5302-8e77-684360c2293e', '2c4d6cbd-6838-5c12-ac11-2a3b974e8f7c', '2026-27', 'application', 'RD', 'Regular Decision', '2027-01-05', '2027-04-01', 'Notification ''by Apr. 1''; enrollment deposit due May 1; FAFSA and CSS Profile priority Feb 1, final Mar 1.', 'ddd11abb-0393-5735-8680-655a0cffbc28');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('2c4d6cbd-6838-5c12-ac11-2a3b974e8f7c', 'recommended', 'Strongly recommended if English is not your native language and your schooling in the past four years or more was in another language; applicants who spoke another language at home should also strongly consider it. Duolingo is accepted when TOEFL/IELTS are not accessible.', 'e3b59768-119e-5339-893c-a75e670567f9');
insert into english_requirements (institution_id, source_id, test_key, status, recommended_total, notes)
