insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('3a4758e1-f1ed-51fc-9bb9-6d18d1454424', '2026-27', 'optional', 'Williams describes itself as truly test optional; SAT/ACT is superscored if submitted (including across legacy and enhanced ACT); ACT Science is optional. Applicants may change their mind about submitting before the deadline.', 'ebb9b206-6781-563e-8b50-b8c7671be68f');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, interview, app_fee_usd, notes, source_id) values
 ('3a4758e1-f1ed-51fc-9bb9-6d18d1454424', '2026-27', array['common_app','coalition','questbridge']::text[], false, 2, true, 'not_offered', 65, 'Common App, Apply Coalition with Scoir, or QuestBridge. No required writing supplement (an academic writing sample is optional). Counselor letter plus two teacher letters; mid-year report due Feb 6. Williams does not conduct interviews (InitialView interviews may be shared). The pages do not print the entry year; dates are treated as the fall 2027 cycle (the aid page references 2027-2028).', 'ebb9b206-6781-563e-8b50-b8c7671be68f');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('467b4284-4d13-5bca-8968-941a611a7e2c', '3a4758e1-f1ed-51fc-9bb9-6d18d1454424', '2026-27', 'application', 'ED', 'Early Decision (binding)', '2026-11-15', '2026-12-14', 'Admission and financial aid applications are due at the same time. Page says decision ''by December 14''.', 'ebb9b206-6781-563e-8b50-b8c7671be68f'),
 ('c84aa3e4-07b8-5aae-8726-e9495dfca1ab', '3a4758e1-f1ed-51fc-9bb9-6d18d1454424', '2026-27', 'application', 'RD', 'Regular Decision', '2027-01-04', '2027-04-01', 'Answer April 1; reply by May 1.', 'ebb9b206-6781-563e-8b50-b8c7671be68f');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('3a4758e1-f1ed-51fc-9bb9-6d18d1454424', 'recommended', 'If English is not your first language or the language of academic instruction at your school, Williams encourages you to submit TOEFL, IELTS or Duolingo scores (self-report, email a screenshot, or send from the testing agency). Scores of enrolling students are verified. No minimums are published; the figures below are the typical range of competitive applicants.', '4ce668cf-7db1-5dca-a1fc-32cc2af57400');
